window.TAGINFO={"Aldric Vorn Arkwright":{"t":"c","sub":"Ark Armatech’in kurucusu · mühendis","bio":["Balahnur’un kuzey sanayi bölgesinden, silahçı Arkwright ailesinden gelen bir insan mühendis. Ailesi o 8 yaşındayken öldürüldü; on yıl sonra, 18 yaşında, katillerden birinin izini sürüp onu öldürdü ve Barışbozan yüzüğünü aldı.","Kıtanın en büyük savaş teknolojisi şirketi olmayı hedefleyen Ark Armatech’i kurdu. Halk önünde sakin bir iş insanı; içinde öfke ve ağır bir yük taşıyor. Güney Toprakları’nda Kâtip Pirdeviz’in sunduğu hikmetler arasından ölümsüzlüğü seçti.","River Lane’in sevgilisi; Serylda’ya babalık ediyor ve Serylda ona “baba” diyor. Barışbozan yüzüğünü River için yaktı. Balahnur’un düşüşünden sonra Ark Armatech’i Mital Alari’de yeniden kurdu."],"facts":[["Irk","İnsan"],["Sınıf","Mühendis (Engineer)"],["Köken","Balahnur, Kuzey Sanayi Bölgesi"],["Ekip","The Last Bad Decision"]],"alias":["Aldric","Aldric Arkwright"],"ph":[{"f":"assets/tagimg/23cdfaca621b.webp?v=ed97c10a80","w":933,"h":1400,"cap":"Zırhlı bordo-altın palto"},{"f":"assets/tagimg/22791329c380.webp?v=e5ae3e63a2","w":1254,"h":1254,"cap":"Portre"},{"f":"assets/tagimg/e50a335f58a6.webp?v=e94caa82da","w":1400,"h":601,"cap":"Balahnur sokaklarında, gece"}]},"Gideon Blackwood":{"t":"c","sub":"Containment Marshal · Pox Master","bio":["Ekibin üyesi olan insan bir cadı avcısı. Veba doktorlarına (Pox Master’lar) katıldı ve Containment Marshal oldu; Pox Sanctum’da ofisi, 69. Cadde’de karakolu vardı.","Kapsül lanetiyle sol omzu kuma dönüştü; Aldric ona S.A.R.M kolunu yaptı. Balahnur felaketinde Pox Master’larla imparatorluk yönetimine karşı ayaklandı ve yaklaşık 500 bin kişinin tahliyesinden sorumlu oldu.","Daria ile evli. Mital Alari’de elflerle birlikte şehir yönetim konseyini kurdu."],"facts":[["Irk","İnsan"],["Unvan","Containment Marshal"],["Eşi","Daria Blackwood"],["Ekip","The Last Bad Decision"]],"alias":["Gideon"],"ph":[{"f":"assets/tagimg/d2c351311b2f.webp?v=28bcff780d","w":932,"h":1400,"cap":"Maskesiz zırhıyla"},{"f":"assets/tagimg/a9792d54e79e.webp?v=9f80012ac0","w":1050,"h":1400,"cap":"Savaş alanında"},{"f":"assets/tagimg/457fcd9c65ec.webp?v=54bc653254","w":1120,"h":1400,"cap":"Order of the Emerald Eye üniforması"}]},"Ayrton Octappen":{"t":"c","sub":"Polymorph · yarışçı · Velocis’in sahibi","bio":["Biçim değiştirebilen (polymorph) insan bir yarışçı; Aldric’i ağabeyi gibi görür. Babası “Winged Bull” Fernando Lauda Octappen’dir. Bir kazada bacaklarını kaybetti; Ark Armatech yapımı mekanik protez bacaklarıyla koşar.","Narnia yarışını kazandı. Aldric ona, hızlandıkça hasarı artan Velocis mızrağını yaptı. Herkenoff suç ağına sızıp Fedai’den Reis’e yükseldi.","Balahnur’un düşüşünde Reiner Herkenoff’u mızrakla infaz etti. Pride ve Vanity sinomorph’larını feda ederek abisi Daniel’i eski hâline getirdi. Levi, Rem, Ram ve Omux ile evlidir."],"facts":[["Irk","İnsan"],["Sınıf","Polymorph / Rogue"],["Silahı","Velocis (mızrak)"],["Bacaklar","Ark Armatech mekanik protez"]],"alias":["Ayrton"],"ph":[{"f":"assets/tagimg/b5f35c5079cb.webp?v=9c740ba7a3","w":933,"h":1400,"cap":"Karlı gecede"},{"f":"assets/tagimg/bb0364df59be.webp?v=c70229ebdd","w":932,"h":1400,"cap":"Kürk yakalı paltoyla"},{"f":"assets/tagimg/d5735ccb0258.webp?v=abaec1477c","w":1400,"h":788,"cap":"Velocis mızrağı"}]},"Julius Vane":{"t":"c","sub":"Ozan · “Silver Voice”","bio":["Kısa gümüş-beyaz saçlı, insan bir ozan. “Silver Voice” adıyla anlattığı kahramanlık hikâyeleri gerçek değildi. The Hundred Blades dört yıl önce köyünü yaktı; annesini ve sevgilisi Anastasia’yı koruyamadı.","İblis Nyxara ile yıllardır süren bir anlaşması vardı. Murat Bey onu buldu ve Aldric onu Ark Armatech’te reklam için işe aldı; ardından The Last Bad Decision’a katıldı. Crownforge ayininde Serylda ile şarkı söyledi ve cadılara esir düştü.","Mital Alari’de bir maceracı loncası kurdu. Nyxara’ya yaptığı fedalardan sonra anlaşmayı bozmak için kendi boğazını kesti; Gideon ile Aldric Nyxara’yı öldürdü. Ses telleri kalıcı olarak gitti: artık “Silent Voice”. Kayıtlarda Julius ile Serylda arasındaki gizli ilişki de geçer."],"facts":[["Irk","İnsan"],["Sınıf","Ozan (Bard)"],["Lakap","Silver Voice → Silent Voice"]],"alias":["Julius"],"ph":[{"f":"assets/tagimg/d88d8887eaa5.webp?v=f77da3ed57","w":557,"h":821,"cap":"Portre"},{"f":"assets/tagimg/0bcf0d9665b6.webp?v=e6de283399","w":1400,"h":787,"cap":"Handa illüzyon kopyalarıyla"}]},"Serylda":{"t":"c","sub":"Aldric’in kanatları altındaki kız","bio":["Aldric’in kurtardığı sağır-dilsiz, kimsesiz bir kız. Aldric’i “baba” diye çağırır; Aldric ve River onun anne babası gibidir.","Pox Sanctum’da False Hydra’nın ses telleri ve derisiyle işitmesi ve sesi geri verildi. Ameliyattan sonra büyüsel nedenlerle birkaç ay içinde hızla büyüyüp 18 yaşına geldi. Prof. Jephcoats’ın Cogito Rezonans cihazı onu denek seçti.","Crownforge ayinini Julius ile şarkı söyleyerek tamamladı. Sesiyle taklit ve iyileştirme yapabilir, hiçlik portalları açabilir. Mital Alari’de Aldric ile eğitim görüyor. Kayıtlarda Julius ile Serylda arasındaki gizli ilişki de geçer."],"facts":[["Yaş","18 (ameliyat sonrası)"],["Yetenekler","Ses taklidi, iyileştiren ses, hiçlik portalları"]],"alias":["Serilyda","Serilda"],"ph":[{"f":"assets/tagimg/e22fb8c162b2.webp?v=4661cf1757","w":960,"h":820,"cap":"Portre"},{"f":"assets/tagimg/fa346fbda007.webp?v=4072973103","w":620,"h":570,"cap":"Wolf-cut saçıyla"}]},"River Lane":{"t":"c","sub":"Aldric’in sevgilisi · cadı","bio":["Aldric’in sevgilisi; ilişkileri Narnia sonrasındaki 40 günlük festivalde başladı. Cadı olduğunu Aldric’ten bir süre sakladı.","Mekanik bir cadı süpürgesi kullanır ve Aldric için yeni bir Vindicator tasarımı yaptı. Ailesi Blavinken ormanlarındaki bir evde zamanın dışında donmuş hâlde bekliyor; Aldric onları kurtaracağına söz verdi.","Balahnur’un düşüşünde portal ve Flash kanisteriyle ekibin kaçışını sağladı. Mital Alari’de Ark Armatech’te çalışıyor ve Serylda’nın eğitimine katılıyor."],"facts":[["Bağ","Aldric’in sevgilisi"],["Ailesi","Blavinken ormanlarında, zamanda donmuş"]],"alias":["River"],"ph":[{"f":"assets/tagimg/61436cc26270.webp?v=40000897b5","w":939,"h":1400,"cap":"Festivalde"},{"f":"assets/tagimg/ea3ccb292b86.webp?v=7d09a84092","w":1400,"h":624,"cap":"Atölyede, Murat Bey ile"}]},"Levi":{"t":"c","sub":"Ayrton’un eşi","bio":["Ekiple birlikte Güney seferine katıldı; Aetherion Magnus’a saldırı sırasında Aldric’le tamir sistemlerini çalıştırdı.","Ayrton’un Herkenoff’a sızmasında onun yanındaydı ve onunla birlikte Reis konumuna yükseldi. Balahnur’un düşüşünden sonra Ayrton ile evlendi."],"facts":[["Sınıf","Warlock / Rogue"]],"ph":[{"f":"assets/tagimg/2bdc65fe0462.webp?v=9b8646b058","w":1209,"h":1300,"cap":"Bordo paltosuyla"},{"f":"assets/tagimg/9d2ccc722d94.webp?v=d11f379a05","w":1199,"h":1312,"cap":"Yanan şehirde"}]},"Daria":{"t":"c","sub":"Daria Blackwood (Gordon)","bio":["Kızlık soyadı Gordon. Gideon Blackwood ile evlenip Daria Blackwood oldu. Gideon’a verdiği bilye, Güney seferinde parçalanınca İmparatoriçe’nin gizli ada teklifi ortaya çıktı.","Ark Armatech çevresinde çalıştı; Balahnur düşerken işçiler ona “müdür hanım” diyordu. Gideon’a cadı olduğunu açıkladı. Mital Alari’de PrideBreaker cihazının büyülenmesine yardım etti."],"facts":[["Eşi","Gideon Blackwood"]],"alias":["Daria Blackwood","Daria Gordon"],"ph":[{"f":"assets/tagimg/9af2399458aa.webp?v=484ba19e8d","w":862,"h":1400,"cap":"Gündelik hâli"},{"f":"assets/tagimg/ed782495d8d9.webp?v=30ab7d8e7b","w":1400,"h":600,"cap":"Gideon ile savaşta"}]},"Murat Bey":{"t":"c","sub":"Ark Armatech atölye yöneticisi","bio":["Ark Armatech’in kısa boylu, telaşlı atölye yöneticisi; Aldric ona “Bay Murat Bey” der.","Hayvan lanetiyle önce Inu oldu: bir süre isteğine göre insan ile insansı porsuk biçimi arasında geçiş yapabildi. Daha sonra kalıcı olarak gerçek bir porsuğa dönüştü ve bir daha insan biçimine dönemedi."],"facts":[["Biçim","İnsan → insansı porsuk → porsuk"]],"ph":[{"f":"assets/tagimg/ee1115adfa86.webp?v=89f7c1852e","w":1400,"h":600,"cap":"İnsansı porsuk hâli"},{"f":"assets/tagimg/ab9891428a85.webp?v=7d09a84092","w":1400,"h":624,"cap":"İnsan hâli, atölyede"}]},"Xar'koth Val'in":{"t":"c","sub":"Kara elf warlock","bio":["220 yaşında erkek bir kara elf; Arrowhul’un alt koridorlarındaki karaborsada doğdu ve Balahnur’da saklanıyordu. Patronu Hiçlik Efendisi’dir.","Ekibe hiçlikten geçen portalıyla Narnia yolculuğunda yardım etti ve False Hydra savaşında yer aldı. Narnia–Nasihir dönüşünün ardından ekipten ayrıldı."],"facts":[["Irk","Kara elf"],["Sınıf","Warlock / Illusionist"],["Doğum yeri","Arrowhul"]],"alias":["Xar'Koth","Xarkoth"],"ph":[{"f":"assets/tagimg/5dc7d46b0cca.webp?v=2e97da8123","w":1400,"h":1045,"cap":"Portre"},{"f":"assets/tagimg/028206b0451e.webp?v=73a222832e","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Revalor Olawarin":{"t":"c","sub":"Elflerin Kralı · Arrowhul’un efendisi","bio":["Arrowhul’un elf kralı. Boraldmir’in 9902’deki dönüşünden sonra insan, elf ve cüceyi birleştirip Büyük Savaş’ı kazandı ve Elflerin Kralı oldu.","Aldric onu Arrowhul’da ikna edince Balahnur’a yardım gönderdi, bizzat gelip düşmüş meleği yendi. Aldric’in omurgasındaki sistem onun emriyle yerleştirildi."],"facts":[["Irk","Elf"],["Unvan","Elflerin Kralı"]],"ph":[{"f":"assets/tagimg/6117ef0ce6e6.webp?v=0537b60db9","w":788,"h":1400,"cap":"Portre"},{"f":"assets/tagimg/ddb459f6488e.webp?v=ea900433ac","w":788,"h":1400,"cap":"Yas tutarken"}]},"Boraldmir":{"t":"c","sub":"Elf kıtasının hâkimi","bio":["9548’de tahta geçti ve Elf Savaşları ile kıtayı aldı; Horaghfus Savaşı’nda Singulken ile Arowuhl’u fethetti. İnsan, elf ve cüce ırklarının birlikte dövdüğü hançerle ruhu hapsedildi.","9902’de geri döndü; ardından Revalor liderliğindeki üç ırka Büyük Savaş’ı kaybetti. Barışbozanlar onun hizmetkârlarıdır."],"facts":[["Irk","Elf"]],"ph":[{"f":"assets/tagimg/82d373d21d99.webp?v=8ce518d208","w":911,"h":1400,"cap":"Boraldmir"},{"f":"assets/tagimg/e0e727f1f395.webp?v=8772ffcad4","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Jephcoats":{"t":"c","sub":"Profesör · Aldric’in eski hocası · Cogito Rezonans","bio":["Aldric’in bir zamanki hocası olan profesör. Kapsül lanetinde ekip ona danıştı. Uygun bir denek aradığını söyleyerek Cogito Rezonans cihazını Aldric’e verdi; cihaz Serylda’yı gösterdi. Serylda’yı Girift Alem’in anahtarı sandı.","Aldric, onları kandırdığı için Jephcoats’u öldürdü. Evinde, mutfak lavabosunun giderinde küçültme büyüsüyle gizlenmiş bir geçit ve False Hydra ile denizanası çizimleriyle dolu bir araştırma odası bulundu.","Odadaki mektuplar, ekibi Ebon Passage’daki Stephen’ın evine Justinianus’a yazdığı mektupla yönlendirdiğini ortaya çıkardı."],"facts":[["Unvan","Profesör"],["Cihazı","Cogito Rezonans"]],"alias":["Prof. Jephcoats","Profesör Jephcoats","Jephcots"],"ph":[{"f":"assets/tagimg/8c2ed27e5ee0.webp?v=8e86d9c4e8","w":1400,"h":781,"cap":"Profesör Jephcoats"},{"f":"assets/tagimg/0919944efa7d.webp?v=36cc20c67d","w":1120,"h":1400,"cap":"Jephcoats (kil görünümlü referans)"}]},"İmparatoriçe":{"t":"c","sub":"İmparatorluğun hükümdarı","bio":["İmparatorun ölümünden sonra tahta geçen kızı. Daria’nın bilye mermisiyle beliren üç kadından ortadakinin o olduğu düşünülür; Aldric’e gizli ada (Project Crownforge) anlaşmasını teklif etti. Kış boyunca ana yolları yalnızca soylulara ve işletme sahiplerine açan fermanı çıkardı.","Crownforge ayininde, Girift Alem’deki beyaz saçlı kadın tarafından Kutsal Elma ile birlikte kaçırıldı; hâlâ kayıp. Adı kaynaklarda geçmiyor."],"ph":[{"f":"assets/tagimg/44849bfd4e5d.webp?v=7c5bd7fed2","w":924,"h":1400,"cap":"İmparatoriçe"},{"f":"assets/tagimg/96f998b1b303.webp?v=a83cfd6b2d","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Nyxara":{"t":"c","sub":"İblis","bio":["Julius’un yıllardır anlaşmalı olduğu iblis. Julius’un şarkıları ve fedalarıyla güçlendi, onu duygusuzlaştırdı ve Serylda’ya göz dikti.","Julius anlaşmayı bozunca Gideon ve Aldric onu ininde öldürdü."],"ph":[{"f":"assets/tagimg/ac51978c4765.webp?v=4a5824ce2d","w":754,"h":824,"cap":"Nyxara"},{"f":"assets/tagimg/fff1ed166114.webp?v=9d8f63bd2c","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Anastasia":{"t":"c","sub":"Julius’un eski sevgilisi","bio":["The Hundred Blades, Julius’un köyünü yaktığından beri dört yıl kayıptı. Hundred Blades kampı katledildiğinde kurtarıldı ve Nyxara’nın inine gidenler arasındaydı."],"ph":[{"f":"assets/tagimg/801fdd8b684f.webp?v=8441f83e90","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Reiner Herkenoff":{"t":"c","sub":"“Suskun Patron”","bio":["Herkenoff ailesinin başındaki mafya babası; Dolunay Çetesi’nin tepesindeki suç ağını yönetiyordu. Ailesinin kökeni Suskun Diyar krallığıdır.","Balahnur’un düşüşünde Herkenoff malikânesi baskınında Ayrton onu mızrakla infaz etti.","Sağ kolu Forrest’tır."],"ph":[{"f":"assets/tagimg/b61065624600.webp?v=6d4ed852a4","w":933,"h":1400,"cap":"Reiner Herkenoff"},{"f":"assets/tagimg/385678de1014.webp?v=6a6adb992d","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Düşmüş melek (Seraphim)":{"t":"c","sub":"Balahnur’a gönderilen melek","bio":["Pride adlı varlığın Balahnur’a yolladığı düşmüş melek. Kral Revalor bizzat gelip onu yendi; melek iki gün sonra cadılar tarafından diriltildi."],"alias":["Seraphim"],"ph":[{"f":"assets/tagimg/4b1b1d97697e.webp?v=6a46c18b69","w":788,"h":1400,"cap":"Seraphim"},{"f":"assets/tagimg/ef106edbacf3.webp?v=c584095f2c","w":933,"h":1400,"cap":"Düşmüş hâli"}]},"Oburluk Cadısı":{"t":"c","sub":"Günah cadılarından","bio":["Balahnur’un düşüşünde gelen günah cadılarından biri."],"ph":[{"f":"assets/tagimg/6d38dbc8fdd3.webp?v=b9d2c01bdf","w":782,"h":1400,"cap":"Oburluk Cadısı"},{"f":"assets/tagimg/7491a0617e17.webp?v=0da0d4f75b","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Melankoli Cadısı":{"t":"c","sub":"Günah cadılarından","bio":["Günah cadılarından biri. Aldric, esir düşen Julius’u onun yanından uçarak aldı."],"ph":[{"f":"assets/tagimg/8eb80e461a7f.webp?v=3b441b09bd","w":896,"h":1200,"cap":"Melankoli Cadısı"},{"f":"assets/tagimg/acc7568bb1e0.webp?v=8b0b75e2b3","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Tom":{"t":"c","sub":"Mital Alari muhafız kaptanı","bio":["Gideon’un askeriydi. Balahnur düşerken Gideon onu River’ın gittiği bölgeye küçük bir ekiple gönderdi. Mital Alari’de şehir muhafızlarının kaptanı oldu."],"ph":[{"f":"assets/tagimg/236910c8b9b3.webp?v=483b9c9582","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Tom Barehand":{"t":"c","sub":"Happy Faces vakası","bio":["Gideon’un Happy Faces hanındaki cinayet soruşturmasında yer alan kişi."],"ph":[{"f":"assets/tagimg/5893c830c42f.webp?v=47802ae0a9","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Trader":{"t":"c","sub":"Zamanı durduran tüccar","bio":["Elf şehrinin sahilinde zamanı 24 saat durdurdu; Ayrton’un düğünü bu sürede yapıldı. Rem ve Ram ona emanet edildi; Ayrton’un ona iki borcu daha var."],"ph":[{"f":"assets/tagimg/717103c678fa.webp?v=d295a585e4","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Kâtip Pirdeviz":{"t":"c","sub":"Güney İmparatorluğu’nun ölümsüz kâtibi","bio":["Güney Toprakları’nda kendini bir piramide mühürlemiş, kadim ve ölümsüz bir saray kâtibi; Güney hükümdarı Ankabar Jinkarin’in kâtibiydi. Aldric’e bir hikmet seçtirdi ve Aldric ölümsüzlüğü seçti."],"alias":["Katip Pirdeviz"],"ph":[{"f":"assets/tagimg/718c5b19954a.webp?v=31503ad939","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Ilrune Araxsys":{"t":"c","sub":"Elf","bio":["Aldric’i tutan elf tesisinde, Aldric’in esareti ve ameliyatı sırasında bulunan elf."],"ph":[{"f":"assets/tagimg/2e6a0db8b392.webp?v=97db132b8a","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Daniel Octappen":{"t":"c","sub":"Ayrton’un abisi","bio":["Ayrton, Pride ve Vanity sinomorph’larını feda ederek onu eski hâline getirdi ve Ark Armatech’e taşıdı."],"ph":[{"f":"assets/tagimg/a0df48ef5b61.webp?v=ab0539ca6c","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Fernando Lauda Octappen":{"t":"c","sub":"“Winged Bull”","bio":["Ayrton’un babası; kanatlı boğa biçimine giren bir polymorph."],"ph":[{"f":"assets/tagimg/eb001fe396d4.webp?v=2b4c99897d","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Omux":{"t":"c","sub":"Ayrton’un eşi","bio":["Ayrton’un eşlerinden biri. Ayrton’un sinomorph dönemlerinde zihninde ona yardım etti."],"ph":[{"f":"assets/tagimg/8bd4bf010439.webp?v=f12bab3a56","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Rem":{"t":"c","sub":"Ayrton’un eşi","bio":["Ayrton’un eşlerinden biri. Ayrton ilk F3 kupasını Rem ve Ram’a verdi."],"ph":[{"f":"assets/tagimg/0f9c15751c8e.webp?v=0ffb5b3571","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Ram":{"t":"c","sub":"Ayrton’un eşi","bio":["Ayrton’un eşlerinden biri. Ayrton ilk F3 kupasını Rem ve Ram’a verdi."],"ph":[{"f":"assets/tagimg/3e916bfdbb23.webp?v=781c483239","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Dilar":{"t":"c","sub":"Herkenoff içindeki bağlantı","bio":["Ayrton’un Herkenoff suç ağı içindeki bağlantısı."],"ph":[{"f":"assets/tagimg/dbff401cee57.webp?v=552648ebc8","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Doktor Einshmirtz":{"t":"c","sub":"Herkenoff doktoru","bio":["Herkenoff’un doktoru. Ark Armatech üzerinden devlet sırlarını öğrenmek için Aldric’in beynini açmak istiyor; Ayrton’u bir susma anlaşmasına zorladı."],"ph":[{"f":"assets/tagimg/d5ba509d25cf.webp?v=a1db51645b","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Cedric":{"t":"c","sub":"Kommisar · eski cadı avcısı · Herkenoff","bio":["Bir zamanlar cadı avcısıydı. Karısı bir av sırasında bir cadı tarafından öldürüldü; Herkenoff çetesi çocuklarını bulup ghoul’a dönüştürünce iki çocuğunu da kendi arbaletiyle öldürdü ve cadı avcılığını bıraktı.","Herkenoff ağında lojistikten ve kurt adamlaştırmadan sorumluydu: Toplayıcıları yönetiyor, kaçırılan insanların sevkiyatını düzenliyordu.","Gideon, Ayrton’un zarflarıyla yerini buldu; Aldric, Ayrton, Gideon, Levi ve Tom onu avladı ve son kurşunu Gideon attı."],"facts":[["Eski mesleği","Cadı avcısı"],["Örgüt","Herkenoff"],["Silahı","Arbalet"]],"alias":["Kommisar Cedric"],"ph":[{"f":"assets/tagimg/d61e10a3a760.webp?v=9d135f9c52","w":1194,"h":1400,"cap":"Kommisar Cedric"},{"f":"assets/tagimg/c6dc6e0a7212.webp?v=b1a091dbde","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Nebukadnezar":{"t":"c","sub":"Narnia’nın Baş Büyücüsü","bio":["Narnia’daki Nasihir Akademisi’nin Baş Büyücüsü. Aldric onun sınavından geçti; Nebukadnezar Aldric’in yüzüğünü ve kapsülünü görünce ona bir büyü kitabı verdi."],"alias":["Nebukadnezzar"],"ph":[{"f":"assets/tagimg/fa59c7204cf2.webp?v=68c8ed5290","w":564,"h":861,"cap":"Nebukadnezar"},{"f":"assets/tagimg/d03318802c20.webp?v=80ccfe6b0b","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Amber":{"t":"c","sub":"Mavi saçlı müzisyen","bio":["Balahnur’da Julius’un çevresindeki mavi saçlı müzisyen."],"ph":[{"f":"assets/tagimg/e82d1d1be008.webp?v=ccb5c548b3","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Ester":{"t":"c","sub":"Amber’in arkadaşı","bio":["Amber’in utangaç, turuncu saçlı arkadaşı."],"ph":[{"f":"assets/tagimg/6de4813aa6bd.webp?v=3a3991c0a9","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Mininem":{"t":"c","sub":"Cüce ozan","bio":["Julius’a rap düellosunda yenilip peşine takılan cüce ozan Mininem Slimshieldy. Nyxara’ya feda edildi."],"ph":[{"f":"assets/tagimg/45b837e7640c.webp?v=e1ba5c29e9","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Velina":{"t":"c","sub":"İmparatoriçe’nin Başmaiden’ı","bio":["İmparatoriçe’nin Başmaiden’ı."],"ph":[{"f":"assets/tagimg/492ede54839d.webp?v=691d4d52fc","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Sedonia":{"t":"c","sub":"Aldric’in ilk büyük iş bağlantısı","bio":["Chavel yarışlarından sonraki haftalarda Aldric’in ihale/anlaşma yaptığı kişi; oyun notlarında “ihaleyi aldığım” kişi diye geçer ve Aldric’in iş dünyasındaki ilk büyük bağlantısıdır.","Güney seferinde River Aldric’e ışınlanan bir mektupla “Sedonia öldü. Artık Ark Armatech’i ve bizi rahatsız edemeyecek” diye yazdı. Aldric River’ın onu ortadan kaldırmış olabileceğini düşündü; mesele River ile aralarında soru işareti olarak kaldı."],"ph":[{"f":"assets/tagimg/60f8a12fd33f.webp?v=4ae383efd3","w":939,"h":1400,"cap":"Sedonia"},{"f":"assets/tagimg/f68b54defdb0.webp?v=d95516b6db","w":939,"h":1400,"cap":"Sedonia, pelerinli"}]},"Vagor":{"t":"c","bio":["Aldric’in aldığı evin yeni sakini olan vampir; öldürüldü."],"ph":[{"f":"assets/tagimg/4a626a460e12.webp?v=c077b5338a","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Ölüm":{"t":"c","sub":"Kapüşonlu kafatası figürü · taşı sürükleyen","bio":["1951’de tek gecede her soylu krala giderek ilk kez kendini gösterdi; hepsine ne işe yaradığını bilmedikleri bir taş verdi, ölene dek saklamalarını söyledi ve hiçbir soruyu cevaplamadan gitti. 2799 Manayutan baskınlarında Ölüm’ün taş verdiği asiller öldükten sonra geri döndü.","Narnia döneminde cadı avcıları, cüce topraklarından zincirli, havada süzülen bir taşı sürükleyen kapüşonlu bir kafatası figürünü rapor etti.","Revalor’a göre batıdan doğuya bir taş sürüklüyor ve durdurulamaz. Aldric onu Aerofall Trimatus’la uçarken Mital Alari kıyısında gördü: doğuya yürüyordu ve arkasındaki taş toprağı yararak onu izliyordu."],"ph":[{"f":"assets/tagimg/6882143332e6.webp?v=0aceaffb66","w":743,"h":988,"cap":"Ölüm ve taşı"},{"f":"assets/tagimg/00a8ecd3f851.webp?v=cd0aab19c9","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Forge (02)":{"t":"c","sub":"The Grafted","bio":["Crownforge deneylerinden sağ kalan dört denekten biri. Denek 02: omurga yük çerçevesi."],"ph":[{"f":"assets/tagimg/0cdb7df0cc07.webp?v=d3e443d2cd","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Null (07)":{"t":"c","sub":"The Grafted","bio":["Crownforge deneylerinden sağ kalan dört denekten biri. Denek 07: alfa kurt adam kanı ve anti-büyü asidi."],"ph":[{"f":"assets/tagimg/dc0b784b8d78.webp?v=187c0d4276","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Veyr (13)":{"t":"c","sub":"The Grafted","bio":["Crownforge deneylerinden sağ kalan dört denekten biri. Denek 13: mekanik göz."],"ph":[{"f":"assets/tagimg/989209fa3587.webp?v=99c6baa085","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Hound (19)":{"t":"c","sub":"The Grafted","bio":["Crownforge deneylerinden sağ kalan dört denekten biri. Denek 19: serumlar ve nöral implantlar; grubun komutanı."],"ph":[{"f":"assets/tagimg/d93eb3b546fc.webp?v=1861cdfd1a","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Mara":{"t":"c","sub":"Julius’un loncası","bio":["Julius’un Mital Alari’deki maceracı loncasının üyesi; ekip seçer."],"ph":[{"f":"assets/tagimg/4fda3a5bc970.webp?v=4539f7174d","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Sasha":{"t":"c","sub":"Julius’un loncası","bio":["Julius’un loncasının iz sürücüsü."],"ph":[{"f":"assets/tagimg/76c0fbee9208.webp?v=4e2b7713c4","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Jorge":{"t":"c","sub":"Julius’un loncası","bio":["Sasha’nın kardeşi; loncanın görev planlayıcısı."],"ph":[{"f":"assets/tagimg/c016766d5539.webp?v=f2630519b3","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Gromur":{"t":"c","sub":"Julius’un loncası","bio":["Loncanın kalkancısı."],"ph":[{"f":"assets/tagimg/5540eb378e0c.webp?v=d441512602","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Vince":{"t":"c","sub":"Julius’un loncası","bio":["Loncada yaralılara bakan üye."],"ph":[{"f":"assets/tagimg/9bdeb4f87046.webp?v=75991d3715","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Jonas Bell":{"t":"c","sub":"Kurt adam","bio":["Gideon’un Happy Faces cinayetleri soruşturmasında eski Pox Sanctum tünellerinde bulunan kurt adam."],"ph":[{"f":"assets/tagimg/1f64bef398c8.webp?v=69046c18d0","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Saul Gortsky":{"t":"c","sub":"Vampir çocuk","bio":["Gideon’un hikâyesindeki vampir çocuk; Gideon ona “Command Bad-blood” kullandı."],"ph":[{"f":"assets/tagimg/99e2dd94aa29.webp?v=25fb6ae0d8","w":1280,"h":720,"cap":"Temsilî çizim"}]},"William Bucks":{"t":"c","sub":"Gideon’un adamı","bio":["Gideon’un emrindeki adamlardan."],"ph":[{"f":"assets/tagimg/a86b327c102b.webp?v=eb09d9579d","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Aldebaran":{"t":"c","bio":["Herkenoff malikânesi baskınında Grukh ile birlikte Erdan Lilov’u indirdi."],"ph":[{"f":"assets/tagimg/0e7351b399eb.webp?v=2d41a185a0","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Grukh":{"t":"c","bio":["Herkenoff malikânesi baskınında Aldebaran ile birlikte Erdan Lilov’u indirdi."],"ph":[{"f":"assets/tagimg/ee2e93b10d4e.webp?v=88170d64ba","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Lierin":{"t":"c","sub":"Lierin Nar Herquel","bio":["Ayrton’un eski sevgilisi; karantinaya alınmış bir meyvenin büyüsüyle kısmen değişti."],"ph":[{"f":"assets/tagimg/af3f43110089.webp?v=316b933604","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Tamrill Ar Aserihn":{"t":"c","sub":"Yüzükteki ses","bio":["Barışbozan yüzüğünden konuşan ses; kendini “Yüce Boraldmir’in hizmetkârı” diye tanıtır."],"ph":[{"f":"assets/tagimg/9c08ce93df05.webp?v=c2834230e7","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Reneagor Sin Boraldmir":{"t":"c","sub":"Boraldmir’in oğlu","bio":["Mülteci krizinde babasına karşı çıktı; darbe girişiminden sonra 150 yaşında sürgün edildi."],"ph":[{"f":"assets/tagimg/a1fb1b4ad19a.webp?v=9daa30f7ec","w":1280,"h":720,"cap":"Temsilî çizim"}]},"An'kabar Jihkari":{"t":"c","sub":"Güney İmparatorluğu hükümdarı","bio":["Güneyli medeniyetlerin imparatoru. 1949’da Kadim Tanrılar Tarikatı’nı kurdurdu, 1961’de elflere saldırdı. Bilgeliğini ritüellerle kapsüllere böldü."],"alias":["Ankabar Jinkarin"],"ph":[{"f":"assets/tagimg/ff4348622fde.webp?v=79c94a3ccb","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Thranduil":{"t":"c","sub":"Elf hükümdarı","bio":["9577’de Gimbatul için İmparatorluk (insanlar) ve Bronzçınar klanı (cüceler) ile savaşan elflerin önderi; Akan Kazan Savaşı’nı kazandı.","Bu savaş yüzünden Horaghfus Savaşı’nda Güneyli Elflere kimse yardıma gitmedi."],"alias":["Thranduil'in Elfleri"],"ph":[{"f":"assets/tagimg/d9967d1bf563.webp?v=82e0601751","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Mythanar Reykalyn":{"t":"c","sub":"Arowuhl kralı","bio":["Kronolojide geçen Arowuhl kralı."],"ph":[{"f":"assets/tagimg/717da429f51b.webp?v=4b5a4a8f3d","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Balahnur":{"t":"p","sub":"İmparatorluğun başkenti","bio":["Batı kıyısında, surlarla çevrili büyük bir liman şehri; imparatorluk sarayı buradadır. Eski Kobold başkentinin yerine 7822’de kuruldu.","Kuzey Sanayi Bölgesi’nde Ark Armatech’in eski atölyesi, 69. Cadde’de Pox Master karakolu vardı. Son olaylarda yandı; halkın büyük kısmı Mital Alari’ye tahliye edildi.","Şehrin merkezinde imparatorluğun kilisesi Vahidan Kilisesi’nin devasa katedrali vardır."],"facts":[["Kuruluş","7822"],["Bölge","Batı kıyısı"]],"ph":[{"f":"assets/tagimg/081fb69371a0.webp?v=f4bd02bff5","w":1400,"h":594,"cap":"Balahnur"},{"f":"assets/tagimg/ddc4ea8db207.webp?v=00086717ce","w":1400,"h":788,"cap":"Gece, havadan"}]},"Ark Armatech":{"t":"p","sub":"Aldric’in şirketi ve binaları","bio":["Aldric’in kurduğu savaş teknolojisi şirketi. Motto: “Order Through Steel”. Balahnur’da önce eski atölye, sonra beyaz gotik genel merkez; Balahnur felaketinde “son kale” oldu.","Tahliyeden sonra Mital Alari’de yeniden kuruldu; elf şehrinde Ark Drive motorları ve Order of the Emerald Eye zırhları üretti."],"facts":[["Kurucu","Aldric Vorn Arkwright"],["Motto","Order Through Steel"]],"alias":["Ark Armatech atölyesi","Ark Armatech ofisi","Ark Armatech kale bölgesi","Ark Armatech surları","Ark Armatech (kale)","Ark Armatech (kraliyet bölgesi atölyesi)","Ark Armatech, atölye katı","Ark Armatech, gizli oda","Ark Armatech üst katı","Ark Armatech (üst kat)","Ark Armatech binası","Ark Armatech çatısı"],"ph":[{"f":"assets/tagimg/10a3e0a13569.webp?v=8261f306f8","w":1024,"h":1024,"cap":"Eski atölye, Balahnur"},{"f":"assets/tagimg/322baa75fbe8.webp?v=6a99c37dcb","w":1024,"h":1024,"cap":"Eski atölye, içeriden"},{"f":"assets/tagimg/43afa2d4c696.webp?v=8cfa152847","w":1400,"h":788,"cap":"Balahnur genel merkezi (genişletilmiş)"},{"f":"assets/tagimg/7e999868d9d5.webp?v=2cf5a5d71c","w":1400,"h":788,"cap":"Atölye salonu"},{"f":"assets/tagimg/b925c88b1f0c.webp?v=868ae4e4cd","w":1400,"h":788,"cap":"Ofis"},{"f":"assets/tagimg/065de9e4a7b5.webp?v=2a887232a9","w":1400,"h":788,"cap":"Çatılar, gece"},{"f":"assets/tagimg/86de85a873e4.webp?v=cd1c4ceb40","w":1400,"h":600,"cap":"Mital Alari şubesi"}]},"Mital Alari":{"t":"p","sub":"Uzak kıtadaki elf kıyı şehri","bio":["Tahliyeden sonra yaklaşık 500 bin Balahnur mültecisinin elf ve cüce yardımıyla yerleştiği eski elf şehri. Elfler ve insanlar karışık yaşıyor; kadim ağaçlar, liman ve sokak portalları var.","Gideon burada elflerle şehir konseyini kurdu; Ark Armatech yeniden kuruldu; Julius maceracı loncasını açtı."],"ph":[{"f":"assets/tagimg/ececeff6a24a.webp?v=2b4fc5c8b3","w":1400,"h":788,"cap":"Şehir, havadan"},{"f":"assets/tagimg/831b76869ec9.webp?v=041a7af8dd","w":1400,"h":788,"cap":"Gece"},{"f":"assets/tagimg/d9290be7450a.webp?v=2ac52ddde0","w":1400,"h":788,"cap":"Ana meydan"},{"f":"assets/tagimg/0cd68000e88a.webp?v=c779cb4a33","w":1400,"h":788,"cap":"Sahil"}]},"Horaghfus":{"t":"p","sub":"Dünya","bio":["Hikâyenin geçtiği dünya ve kıta. Haritada kuzeybatıda Halldor, batı kıyısında Balahnur, kuzeyde Narnia, doğuda Dempur, merkezde Gimbatul, güney ucunda Arowhul yer alır."],"ph":[{"f":"assets/tagimg/cdf320491257.webp?v=4e555231e7","w":1400,"h":1083,"cap":"Horaghfus haritası"},{"f":"assets/tagimg/e4bc2664489f.webp?v=47f4c93523","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Narnia":{"t":"p","sub":"Buzlu denizde kristal kuleli şehir","bio":["Buzlu denizde, renkli kristal kuleli bir kanal şehri. Kötü kalpler için daralan Sırat Köprüsü ve Baş Büyücü Nebukadnezar’ın Nasihir Akademisi buradadır. Ayrton Narnia yarışını burada kazandı."],"alias":["Narnía"],"ph":[{"f":"assets/tagimg/6ec738429cba.webp?v=a97f34f721","w":1400,"h":594,"cap":"Narnia"},{"f":"assets/tagimg/0210898ec1b2.webp?v=963add39d5","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Blavinken":{"t":"p","sub":"8102’de kurulan şehir","bio":["8102’de kuruldu; Narnold soyunun kökeni. Blavinken ormanlarında River’ın ailesinin zamanda donmuş evi bulunur."],"alias":["Blavinken ormanı","Blavinken Krallığı"],"ph":[{"f":"assets/tagimg/f963680a7366.webp?v=9c9cea343a","w":1400,"h":594,"cap":"Blavinken"},{"f":"assets/tagimg/983ecf11d922.webp?v=c9e6a8336a","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Arrowhul":{"t":"p","sub":"Güneydeki elf krallığı","bio":["Kral Revalor Olawarin’in güneydeki elf krallığı; şelaleli bir uçurumun üstünde beyaz saray şehri. Şelale 3426’da dev Ægnádr tarafından oluşturuldu, krallık 3499’da kuruldu. Xar’koth alt koridorlarındaki karaborsada doğdu."],"alias":["Arowuhl","Arowhul","Arrowhul taht odası"],"ph":[{"f":"assets/tagimg/75c32de81a4c.webp?v=a9974b331f","w":1400,"h":600,"cap":"Arrowhul"},{"f":"assets/tagimg/74d6cff25c35.webp?v=68a54695b0","w":1400,"h":788,"cap":"Saray girişi"},{"f":"assets/tagimg/fd35efa3aadb.webp?v=8f24a16765","w":1400,"h":788,"cap":"Taht odası"}]},"Güney Toprakları":{"t":"p","sub":"Antik Güney İmparatorluğu’nun toprakları","bio":["Kayalık çöl kıyıları, devasa kapılı bir nehir ve deniz feneri kulesiyle bilinen güney kıtası. An’kabar Jihkari’nin eski medeniyeti buradaydı; Kâtip Pirdeviz bir piramitte yaşar. Kapsül lanetini kaldırmak için ekip buraya sefer düzenledi."],"alias":["Güney kıtası"],"ph":[{"f":"assets/tagimg/f3996afa5d50.webp?v=e6499d4eb0","w":1400,"h":788,"cap":"Güney Toprakları"},{"f":"assets/tagimg/33915eec70b6.webp?v=d40ccd8d13","w":1400,"h":600,"cap":"İlk varış"},{"f":"assets/tagimg/8e979b190cb2.webp?v=282fab80c8","w":1400,"h":600,"cap":"Kum tepeleri"}]},"Pox Sanctum":{"t":"p","sub":"Veba doktorlarının merkezi","bio":["Veba doktorlarının (Pox Master’lar) merkezi. Serylda burada iyileştirildi; Gideon’un Containment Marshal ofisi buradaydı. Eski tünellerinde kurt adam Jonas Bell saklanıyordu."],"alias":["Gideon'un ofisi, Balahnur"],"ph":[{"f":"assets/tagimg/49f0849d4b1e.webp?v=c900f71869","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Aetherion Magnus":{"t":"p","sub":"Hava gemisi","bio":["Güney seferinde kullanılan hava gemisi: zeplin gövdesinin altında ahşap bir kalyon."],"ph":[{"f":"assets/tagimg/aaf017eb5005.webp?v=763a1fe1ff","w":1400,"h":781,"cap":"Dış görünüş"},{"f":"assets/tagimg/894bbce0154b.webp?v=1143928e65","w":1400,"h":781,"cap":"Makine dairesi"}]},"Crownforge adası":{"t":"p","sub":"İmparatoriçe’nin gizli adası","bio":["İmparatorluğun şövalye seçimini yaptığı gizli ada (Project CROWNFORGE): yedi haftalık bir sınav düzeni, merkez kompleks ve yönetim kompleksi. Crownforge ayini burada yapıldı."],"ph":[{"f":"assets/tagimg/a3e0ddeba060.webp?v=4f5ebb650d","w":1400,"h":784,"cap":"Amfi"},{"f":"assets/tagimg/703904575caa.webp?v=388fa9c3d8","w":1400,"h":933,"cap":"Altıncı sınav alanı"}]},"Girift Alem":{"t":"p","bio":["Kara güneşli, dev denizanalarının süzüldüğü başka bir âlem. Jephcoats, Serylda’yı buranın anahtarı sandı; Serylda Girift Alem’e kapı açabiliyor."],"ph":[{"f":"assets/tagimg/4c9966e362bf.webp?v=eeb9d2cc9a","w":1400,"h":600,"cap":"Girift Alem"},{"f":"assets/tagimg/9313d00a1b7a.webp?v=f25b1fe241","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Ebon Passage":{"t":"p","bio":["False Hydra ile savaşılan geçit; Aldric burada öldü ve dirildi."],"ph":[{"f":"assets/tagimg/e156c5e30f3d.webp?v=7492961361","w":1400,"h":600,"cap":"Ebon Passage"},{"f":"assets/tagimg/0bc9da935441.webp?v=9371b6ae1b","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Chavel":{"t":"p","bio":["Yarışların yapıldığı yer. Ekibin kayıtlı ilk oturumlarında (Session 4–5) Aldric burada Veridus pilotu Fenzo Verrori’nin aracını gördü."],"alias":["Yarış pistleri"],"ph":[{"f":"assets/tagimg/91d80f033136.webp?v=9743ae0593","w":1400,"h":600,"cap":"Chavel yarışları"},{"f":"assets/tagimg/cbb765a893ff.webp?v=04e0045323","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Asgar Üniversitesi":{"t":"p","bio":["Kampanyanın başındaki mekânlardan; kütüphanesi de vardır. Aldric, Sedonia ihalesinden sonra bu üniversite üzerinden bir objeyi tanıyabilecek Stefen’in, Jessie’nin ve evde yeni yaşayan Vagor’un izine düştü."],"alias":["Asgar Kütüphanesi"],"ph":[{"f":"assets/tagimg/1a1a669bbd91.webp?v=ad7868a96c","w":1400,"h":600,"cap":"Asgar Üniversitesi Kütüphanesi"},{"f":"assets/tagimg/9304ae2aaa0a.webp?v=1e7ec4f137","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Gimbatul":{"t":"p","sub":"Merkezî bölge","bio":["Haritanın merkezindeki bölge; Akan Kazan Savaşı (9577) ve Dwarrebanih Savaşı’nın yeri."],"ph":[{"f":"assets/tagimg/251d8141c2c1.webp?v=f9e45c0bc2","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Dempur madeni":{"t":"p","sub":"Cüce madeni","bio":["Strömbah dağında kurulan cüce madeni (2119); Kanunsuz Dönem’de güvenli yerlerden biriydi. Rat’tor Garaz baskını burada yaşandı (5113)."],"ph":[{"f":"assets/tagimg/c1686ce5aa81.webp?v=78e362ff06","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Strömbah dağı":{"t":"p","sub":"Cüce dağı","bio":["Cüce dağı ve başkenti; Dempur madeni bu dağda kuruldu."],"ph":[{"f":"assets/tagimg/9333cb05771d.webp?v=d45525b44b","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Singulken":{"t":"p","bio":["Boraldmir’in Horaghfus Savaşı’nda ilk ele geçirdiği yer."],"ph":[{"f":"assets/tagimg/2567aaf55419.webp?v=2ce07dc8e4","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Karasırt":{"t":"p","sub":"Yeraltı şehri","bio":["2125’te kurulan yeraltı şehirlerinden; 2799’da Manayutanlar tarafından basıldı."],"ph":[{"f":"assets/tagimg/23d729d9120d.webp?v=8786ea6dec","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Tor'araf":{"t":"p","sub":"Yeraltı şehri","bio":["2125’te kurulan yeraltı şehirlerinden; 2799’da Manayutanlar tarafından basıldı."],"ph":[{"f":"assets/tagimg/223625915cc1.webp?v=876e45a865","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Yemin":{"t":"p","sub":"Yeraltı şehri","bio":["2125’te kurulan yeraltı şehirlerinden; 2799’da Manayutanlar tarafından basıldı."],"ph":[{"f":"assets/tagimg/42a622ca4f2a.webp?v=306093925a","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Suskun Diyar":{"t":"p","bio":["Blavinken’in batısındaki yarımadada bir krallık; Herkenoff ailesinin köken krallığı."],"alias":["Suskun Diyar Krallığı"],"ph":[{"f":"assets/tagimg/c57e76818e3f.webp?v=aa624295a2","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Halldor krallığı":{"t":"p","bio":["Balahnur’un kuzeyindeki krallık."],"alias":["Halldor"],"ph":[{"f":"assets/tagimg/961d18e5b14e.webp?v=4d25010534","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Nasihir Akademisi":{"t":"p","sub":"Narnia’daki büyü akademisi","bio":["Büyülerin yıkıcı gücü fark edildikten sonra Horaghfuslu krallıkların büyücüleriyle 9763’te kurduğu akademi. Bitmek bilmeyen saldırılar sonucunda büyücüler 9778’de çekildi ve akademi dağıldı.","Kampanya döneminde Narnia’da, Baş Büyücü Nebukadnezar’ın yeridir: Aldric burada bir ateş büyücüsünden mürekkep aldı ve Nebukadnezar’ın sınavından geçti. Balahnur’un düşüşünde Gideon, buzun içinde bulunan keskinayazdaki hastalığı burada kara buzla dondurttu."],"ph":[{"f":"assets/tagimg/6284c561130c.webp?v=2354239ff4","w":1400,"h":781,"cap":"Akademinin avlusu"},{"f":"assets/tagimg/4bec3efdf2df.webp?v=950cb941c3","w":1400,"h":933,"cap":"Büyük salon"},{"f":"assets/tagimg/33b501a72e64.webp?v=990bf7bfbe","w":1400,"h":594,"cap":"Yargı salonu"}]},"Sırat Köprüsü":{"t":"p","bio":["Narnia’da, kötü kalpler için daralan köprü."],"ph":[{"f":"assets/tagimg/6359b77c3e2f.webp?v=eb6c56a9ac","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Happy Faces Hanı":{"t":"p","bio":["Balahnur’da, Gideon’un kurt adam cinayetlerini soruşturduğu han."],"ph":[{"f":"assets/tagimg/97e6e00dd774.webp?v=f885a86e58","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Beaver Street":{"t":"p","bio":["Balahnur’da, geciken kış erzakı yüzünden isyan çıkan sokak."],"alias":["Beaver sokağı"],"ph":[{"f":"assets/tagimg/652ac6370853.webp?v=6f6f78cc91","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Bitliayak Hanı":{"t":"p","bio":["Balahnur’un batı kapısı dışındaki balıkçı köyünde bir han."],"alias":["Balahnur, Bitliayak Hanı"],"ph":[{"f":"assets/tagimg/d329088af908.webp?v=5a41d8c6da","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Nyxara'nın ini":{"t":"p","bio":["Julius’un iblisi Nyxara’nın yeri; Glasswood’un ötesindeki mağaralarda. Nyxara burada öldürüldü."],"alias":["Nyxara'nın mağarası","Glasswood'un kuzeyindeki mağaralar"],"ph":[{"f":"assets/tagimg/3891fb54e292.webp?v=81a2201bcb","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Herkenoff malikânesi":{"t":"p","bio":["Herkenoff ailesinin malikânesi; Balahnur’un düşüşünde baskın yapıldı."],"alias":["Balahnur dışındaki eski malikâne"],"ph":[{"f":"assets/tagimg/a90fb80a75a1.webp?v=347592d730","w":1280,"h":720,"cap":"Temsilî çizim"}]},"The Last Bad Decision":{"t":"f","sub":"Oyuncu ekibi","bio":["Ekibin adı: False Hydra’nın yenilmesinin hemen ardından alındı. Aldric, Gideon, Ayrton, Xar’koth ve sonradan Julius bu ekiptedir."],"ph":[{"f":"assets/tagimg/573b31355abe.webp?v=e4bba3c28c","w":933,"h":1400,"cap":"Ekip afişi"}]},"Pox Masters":{"t":"f","sub":"Veba doktorları","bio":["İmparatorluğun biyolojik tehditlerle uğraşan kolu: karantina, işletme mühürleme, mezar açma. Gideon onlara katıldı; Balahnur felaketinde Pox Master’larla imparatorluk yönetimine karşı ayaklandı.","Kolun başında Balahnur sarayında oturan Plague Kaiser vardır; enfekte köyü halkıyla birlikte yok etme hükmü (“Kaiser’s Neglect”) ona aittir. Üstünde yalnızca Sacra Quarantina bulunur: imparator ve imparatoriçe dışında herkese emir verebilir."],"ph":[{"f":"assets/tagimg/3e2969d7eafb.webp?v=c7a589714d","w":1254,"h":1254,"cap":"Order of the Emerald Eye arması"},{"f":"assets/tagimg/5ee8d9829c40.webp?v=66211f1f07","w":758,"h":927,"cap":"Plague Kaiser"},{"f":"assets/tagimg/27309fe99e67.webp?v=a2be9b3c1d","w":1400,"h":781,"cap":"Sacra Quarantina"}]},"İmparatorluk":{"t":"f","sub":"İnsan İmparatorluğu","bio":["9450’de Kutsal Elma taşıyıcısı Narnold’un insan krallıklarını birleştirmesiyle kuruldu. İmparatorun ölümünden sonra kızı İmparatoriçe tahta geçti.","Hanedan üyelerinden Prens Michael batıya keşfe çıktı; Prens Ezreal Balahnur’da kalıp Dritorial Collegium’u yönetti. İmparatorluğun kilisesi Vahidan Kilisesi’dir."],"ph":[{"f":"assets/tagimg/d9779c989544.webp?v=500eacbe1c","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Herkenoff":{"t":"f","sub":"Herkenoff ailesi ve suç ağı","bio":["Herkenoff Alchemy ve Madencilik görünen yüzü, Dolunay Çetesi sokak kolu olan suç ağı; başında Reiner Herkenoff vardı. Ayrton bu ağa sızdı.","Reiner Herkenoff’un sağ kolu Forrest’tır."],"alias":["Herkenoff Alchemy","Herkenoff Ailesi"],"ph":[{"f":"assets/tagimg/284ffe29c84d.webp?v=69c81192bd","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Dolunay Çetesi":{"t":"f","bio":["Balahnur yeraltı düzeninin büyük parçası; Herkenoff ailesinin yönettiği suç ağının sokak kolu. Lideri Ayrton’u Narnia yarışını kazanmaya zorladı."],"ph":[{"f":"assets/tagimg/6f56735e9ee3.webp?v=e46353997b","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Cadılar":{"t":"f","bio":["Crownforge’daki tüm katılımcılar cadıydı; İmparatoriçe’yi ve Kutsal Elma’yı aldılar."],"ph":[{"f":"assets/tagimg/e8709b15b929.webp?v=24b7ea1e88","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Üçlü İttifak":{"t":"f","bio":["Elfler, cüceler ve insanlardan oluşan ittifak; Büyük Savaş’ta Revalor Olawarin’in üç ırkı Boraldmir’e karşı birleştirmesinin mirasıdır.","Balahnur düşerken Kral Revalor bu ittifak adına Balahnur’a yardım gönderdi."],"ph":[{"f":"assets/tagimg/f3b0687a5b21.webp?v=50903f0c01","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Project Crownforge":{"t":"f","bio":["Crownforge adasındaki yedi haftalık şövalye seçimi."],"ph":[{"f":"assets/tagimg/81ed68c6c794.webp?v=3b8b1ffd8f","w":1400,"h":933,"cap":"Gizli ada"},{"f":"assets/tagimg/e80bc8a7f567.webp?v=51c334660d","w":1400,"h":933,"cap":"Merkez kompleks"}]},"Julius'un loncası":{"t":"f","sub":"Mital Alari","bio":["Julius’un Mital Alari’de kurduğu maceracı loncası. Kuralları: “Siviller önce gelir / Hiçbir üye geride bırakılmaz / Her görev gerçekte olduğu gibi kaydedilir.”"],"alias":["Julius'un maceracı loncası"],"ph":[{"f":"assets/tagimg/d0a8b4223e12.webp?v=647072f7c4","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Hundred Blades":{"t":"f","sub":"Haydut çetesi","bio":["Julius’un köyünü dört yıl önce yakan haydut çetesi; kampı Gideon ve Aldric’in desteğiyle katledildi."],"alias":["The Hundred Blades"],"ph":[{"f":"assets/tagimg/7384115390e0.webp?v=a7d7b801ee","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Barışbozanlar":{"t":"f","sub":"Peacebreakers","bio":["Boraldmir’in hizmetkârları. Aldric’in ailesini öldüren kara elf de onlardan biriydi."],"ph":[{"f":"assets/tagimg/8c5cc16bfec7.webp?v=af043e04a6","w":1280,"h":720,"cap":"Temsilî çizim"}]},"The Grafted":{"t":"f","sub":"Crownforge denekleri","bio":["Crownforge deneylerinden sağ kalan dört denek: Forge, Null, Veyr ve Hound."],"ph":[{"f":"assets/tagimg/e31dd982082d.webp?v=02ba73193d","w":1400,"h":788,"cap":"Grafted koğuşu"},{"f":"assets/tagimg/0d7f863c5bd2.webp?v=77d8d1a773","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Tomahawk Coşucuları":{"t":"f","bio":["Girift Alem’e geçişte kullanılan Crisp-tease bileşiğini sağlayan gizli çete. Bilinç dışı deneyimler ve psikoaktif bileşikler konusunda derin bilgiye sahiptirler; Crisp-tease en çok rağbet gören ama yüksek risk taşıyan maddeleridir.","Aldric ve River, Jephcoats’un araştırma odasında Crisp-tease’in bu çeteden geldiğini öğrendi."],"alias":["Tomahawk Koşucuları"],"ph":[{"f":"assets/tagimg/12791441be4b.webp?v=6bbb33dd00","w":736,"h":1104,"cap":"Çetenin lideri (referans 1)"},{"f":"assets/tagimg/206c71b577cc.webp?v=f451530d18","w":896,"h":1344,"cap":"Çetenin lideri (referans 2)"},{"f":"assets/tagimg/3b78de1c99e7.webp?v=b092256666","w":736,"h":977,"cap":"Çetenin lideri (referans 3)"}]},"Ratarr Tarikatı":{"t":"f","bio":["Aldric’i Balahnur’un batısındaki sarmaşıklı yapıda tutan paralı asker düzeni."],"alias":["Ratarr Order"],"ph":[{"f":"assets/tagimg/538e07fa54e0.webp?v=5386d4dc61","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Paarthonax":{"t":"c","sub":"Kadim ejderha","bio":["Konuşabilen ve büyü yapabilen kadim bir ejderha; kendine ait bir hikâyesi vardır.","Devasa ve kadim bir ejderha. 4012’de batmakta olan Güney kıtasından Kobold ormanlarına doğru uçtu ve ormanlara girdikten sonra bir daha görülmedi. Bu olaydan sonra Kobold topraklarında bereket arttı.","Boraldmir’in yenildiği son savaştan (Büyük Savaş) hemen önce Deathwing ile Paarthonax özgür kaldı. Savaş sürerken ikisi gökyüzünde birbiriyle savaştı; savaştan sonra ikisi de bir daha ortalıkta görünmedi."],"facts":[["Tür","Ejderha"]],"ph":[{"f":"assets/tagimg/2386f58e69e6.webp?v=7a45bd0eac","w":735,"h":647,"cap":"Paarthonax"},{"f":"assets/tagimg/2620e189ea10.webp?v=482aadff5b","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Keskinayazlar":{"t":"f","sub":"Kar fırtınası yaratıkları","bio":["Yalnızca kar fırtınalarında ortaya çıkan, aşırı hızlı ve fırtınada görünmez bir yaratık türü. 2081’de keşif yapan cüceleri onlara neyin saldırdığını göremeden katlettiler ve keşifleri neredeyse imkânsız hâle getirdiler.","Cüceler madenlerde silahlara işlenen bir tılsım dövünce keskinayazlara karşı büyük avantaj kazandı (Sivritılsım Savaşı). 2117’de Kutsal Elmayı taşıyan koruyucu şövalye Abdiel onlarla savaşırken öldü; hedefleri elma değildi ve elma bir buzun içinde kaldı.","Balahnur’un düşüşünde Herkenoff malikânesinde buzun içinde bir “keskinayaz” bulundu; Gideon içindeki hastalığı şişeye aldı."],"alias":["Keskinayaz"],"ph":[{"f":"assets/tagimg/7f8c9d255ffc.webp?v=8d1e8451e0","w":1280,"h":1127,"cap":"Keskinayaz"},{"f":"assets/tagimg/33c4bd326629.webp?v=2216aa5062","w":912,"h":835,"cap":"Buzun içindeki keskinayaz"}]},"Fedai":{"t":"f","sub":"Herkenoff ağının en kalabalık rütbesi","bio":["Herkenoff suç ağında çoğunluğu sokak serserilerinden oluşan en kalabalık rütbe; Fedai gruplarını Reis’ler yönetir.","Ayrton ve Levi sızma sırasında güçsüz bir Fedai’ye ruhlu bir yüzük taktırdı, sonra Fedai’den Reis’e yükselip küçük bir Fedai birliğinin başına geçti. Levi’yi döven yedi Fedai’yi Wrath’ın etkisindeki Ayrton öldürdü."],"alias":["Fedai'ler","Fedailer"],"ph":[{"f":"assets/tagimg/fb3e69b7dfe2.webp?v=07021cbc01","w":1254,"h":1254,"cap":"Fedai’ler"},{"f":"assets/tagimg/f3bd6bb4228c.webp?v=114ae826bf","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Erdan Lilov":{"t":"c","sub":"Profesör · Herkenoff","bio":["Herkenoff ağında Dolunay Çetesi’nin ihtiyaç duyduğu uyuşturucuları üreten profesör; Velizar Plamenov ölünce yerine geçti. “Denek” rütbesindekiler, gönüllü olarak ya da bağımlılık yüzünden onun deneylerinde kullanılır.","Ekibin görev dağılımında Erdan Lilov ve Doktorları Aldebaran’a düştü. Balahnur’un düşüşündeki malikâne baskınında Aldebaran ve Grukh onu indirdi."],"facts":[["Örgüt","Herkenoff"]],"alias":["Profesör Erdan Lilov"],"ph":[{"f":"assets/tagimg/e9970f1df429.webp?v=716c40163d","w":736,"h":1307,"cap":"Erdan Lilov"},{"f":"assets/tagimg/8a41d8e04306.webp?v=13feab5e2f","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Keira Pirus":{"t":"c","sub":"Herkenoff · sorcerer polymorph","bio":["Herkenoff ağında otelcilik, fuhuş ve şantaj işlerinden sorumlu; bir sorcerer polymorph. Büyülü eşyalara düşkündür, otele gelen rütbelilerden sürekli hediyeler alır; Balahnur banka müdürünün onu düzenli ziyaret ettiği görülmüştür.","Ekibin görev dağılımında Keira Pirus ve Müdürleri, Dilar ile ruhlu yüzüğe bırakıldı."],"facts":[["Örgüt","Herkenoff"],["Sınıf","Sorcerer polymorph"]],"alias":["Pirus"],"ph":[{"f":"assets/tagimg/fe60162ab5a8.webp?v=9efb8661d8","w":736,"h":1104,"cap":"Pirus"},{"f":"assets/tagimg/cd1cf6dcc8cd.webp?v=f806da7895","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Justinianus":{"t":"c","sub":"Profesör","bio":["Ebon Passage’da Aldric öldükten sonra, diriltilmeden önce gelip cesedine bastı ve ekibi aşağıladı; Aldric bu ismi unutmadı. Pis sırıtışı ve üstten bakan sesiyle hatırlanır.","Jephcoats’un araştırma odasındaki mektuplarda geçer: Jephcoats ona aradığı özellikteki deneği Ebon Passage’daki Stephen’ın evinde bulabileceğini yazmıştır. Justinianus’un Prof. Regan’a belirli frekanslara uyumlu yaratıklar hakkında yazdığı mektup ve Askar müdürüne Libby Brown’ın araştırma bütçesi için yazdığı not da oradadır."],"facts":[["Unvan","Profesör"]],"alias":["Justinyanus","Profesör Justinianus","Prof. Justinianus"],"ph":[{"f":"assets/tagimg/01b2c339adb9.webp?v=dd202f09c8","w":736,"h":1236,"cap":"Profesör Justinianus"},{"f":"assets/tagimg/d47402477b4c.webp?v=c7062a115b","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Hexenkommissar":{"t":"f","sub":"İmparatorluğun cadı avcıları","bio":["Doğaüstü yaratıklar, hayaletler ve cadılarla mücadele eden imparatorluk teşkilatı. Rütbeler Folk’s Pioneer çıraklarından Hexenkommissar, Grand ve Margrave Hexenkommissar’a, en tepede Balahnur sarayında oturan Arch-elector Hexenkommissar’a uzanır. Arch-elector Kutsal Elmanın kullanılması hükmünü verebilir.","Exorcist, Sin Catcher ve Blaze Sunderer kolları da vardır. Camerlengo, Arch-elector ya da Plague Kaiser öldüğünde geçici olarak yerlerine geçer.","Narnia döneminde cadı avcıları zincirli bir taşı sürükleyen kapüşonlu kafatası figürünü (Ölüm) rapor etti. Kommisar Cedric de bir zamanlar cadı avcısıydı."],"alias":["Cadı avcıları","Hexenkommissarlar"],"ph":[{"f":"assets/tagimg/753c741a767b.webp?v=d2bf40f8ac","w":933,"h":1400,"cap":"Arch-elector Hexenkommissar"},{"f":"assets/tagimg/668815456688.webp?v=2933481a5f","w":736,"h":1313,"cap":"Camerlengo"}]},"Deathwing":{"t":"c","sub":"Kadim ejderha","bio":["Konuşabilen ve büyü yapabilen kadim bir ejderha; kendine ait bir hikâyesi vardır.","Boraldmir’in yenildiği son savaştan (Büyük Savaş) hemen önce Deathwing ile Paarthonax özgür kaldı. Savaş sürerken ikisi gökyüzünde birbiriyle savaştı; savaştan sonra ikisi de bir daha ortalıkta görünmedi."],"facts":[["Tür","Ejderha"]],"ph":[{"f":"assets/tagimg/0929247c524d.webp?v=dd09752467","w":1400,"h":788,"cap":"Deathwing (tasarım referansı)"},{"f":"assets/tagimg/b0ef39f0461e.webp?v=2c293bf327","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Dorrigat":{"t":"c","sub":"Tabaat İsmail’in canavarı","bio":["Phoenix’in hatırladığı kadarıyla goblin Tabaat İsmail’in hayvanıydı.","Phoenix’in hatırladığı kadarıyla: goblinler Ayrton’un malikânesini ateşe verdikten sonra, Aldric Cogito Rezonans cihazıyla uğraşırken ve ekip Güney topraklarına gitmeden hemen önce, Gideon ile Ayrton gidip goblinlere saldırdı."],"facts":[["Görünüş","Yeşil rün dövmeli, boncuklu, timsaha benzer beyaz bir canavar"]],"ph":[{"f":"assets/tagimg/d3ba4dbaae75.webp?v=4628faaa2d","w":1400,"h":781,"cap":"Dorrigat"},{"f":"assets/tagimg/9b30c0bb3102.webp?v=b2826c11fc","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Tabaat İsmail":{"t":"c","sub":"Goblin · Balahnur kanalizasyon karaborsası","bio":["Gideon’un hikâyelerinde (“Canavarlar ve İnsansılar”) geçer: Balahnur kanalizasyonlarındaki kaçak tünellerden yürüyen karaborsa erzak düzeni, Tabaat Ismael öldürülüp yerine kuzeni getirilince çöktü; bu da kışın fakir halkı zor durumda bıraktı.","Phoenix’in hatırladığı kadarıyla Dorrigat onun hayvanıydı."],"alias":["Tabaat Ismael","Tabaat Ismail"],"ph":[{"f":"assets/tagimg/37c15fe59570.webp?v=e58503244a","w":564,"h":798,"cap":"Tabaat İsmail"},{"f":"assets/tagimg/3d03eef419be.webp?v=fdedb26ebf","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Forrest":{"t":"c","sub":"Reiner Herkenoff’un sağ kolu","bio":["Herkenoff mafyasının adamı; Reiner Herkenoff’un sağ kolu gibidir."],"facts":[["Örgüt","Herkenoff"],["Bağlı olduğu kişi","Reiner Herkenoff"]],"ph":[{"f":"assets/tagimg/896df4c4dc00.webp?v=c4790a0fa1","w":564,"h":752,"cap":"Forrest"},{"f":"assets/tagimg/d4c6fb4dde9b.webp?v=bc10035501","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Vahidan Kilisesi":{"t":"p","sub":"İnsan imparatorluğunun kilisesi · Balahnur","bio":["İnsan imparatorluğunun kilisesi. Balahnur’un merkezinde, halkın gidip ibadet ettiği devasa bir katedral.","İçi dinî paladinler ve şövalyelerle doludur; bunlar sıradan şövalyelerden farklıdır, dine bağlıdırlar ve kutsal büyüde (holy magic) çok güçlüdürler.","Kilisenin başında Vahidan Baş Rahibi vardır; Damriel, Loydelius, Rahal ve Tarnum adlı engizisyoncuları (Inquisitor) da kiliseye bağlıdır. Süper silahı Indomitable Prime II’dir."],"facts":[["Yer","Balahnur, şehir merkezi"]],"alias":["Vahidan","Vahidan Katedrali"],"ph":[{"f":"assets/tagimg/c3f7dcf999ab.webp?v=0b850c7969","w":1400,"h":594,"cap":"Vahidan Kilisesi"},{"f":"assets/tagimg/14ec28e7f3c0.webp?v=66c0c881a5","w":1400,"h":788,"cap":"Katedralin içi"}]},"Indomitable Prime II":{"t":"c","sub":"Vahidan Kilisesi’nin süper silahı","bio":["Vahidan Kilisesi’nin süper silahı: günahkârların günahlarını çekip kutsal büyüyle (holy magic) ateşler.","Kampanyada imparatorluğun son savunması olan prensin çok güçlü gizli silahı Indomitable Prime olarak geçer. Aldric, Julius’u geri almak için prensin ve Indomitable Prime’ın yerini cadılara verdi. Aldric’in günlüğüne göre silah, düşmüş meleği durdurmak ve Balahnur’daki insanları korumak için saklanıyordu."],"facts":[["Sahibi","Vahidan Kilisesi"]],"alias":["Indomitable Prime","Indomitable_Prime_II"],"ph":[{"f":"assets/tagimg/8d403c6873ab.webp?v=3f62a6d047","w":1400,"h":1050,"cap":"Indomitable Prime II"},{"f":"assets/tagimg/f396bf0b77be.webp?v=3f62a6d047","w":1400,"h":1050,"cap":"Temsilî çizim"}]},"Vahidan Baş Rahibi":{"t":"c","sub":"Vahidan Kilisesi","bio":["İnsan imparatorluğunun kilisesi Vahidan Kilisesi’nin baş rahibi."],"facts":[["Kilise","Vahidan Kilisesi"]],"alias":["Vahidan rahibi"],"ph":[{"f":"assets/tagimg/bcd63d408b3d.webp?v=2bdbb1473c","w":1199,"h":1341,"cap":"Vahidan Baş Rahibi"},{"f":"assets/tagimg/072ed0f20066.webp?v=3b5861b6b8","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Vahidan Şövalyeleri":{"t":"f","sub":"Vahidan Kilisesi’nin dinî şövalyeleri","bio":["Vahidan Kilisesi’nin paladinleri ve şövalyeleri. Sıradan şövalyelerden farklıdırlar: dine bağlıdırlar ve kutsal büyüde (holy magic) çok güçlüdürler."],"alias":["Vahidan şövalyesi","Vahidan paladinleri"],"ph":[{"f":"assets/tagimg/91871f86d77a.webp?v=2419305e8c","w":564,"h":769,"cap":"Bir Vahidan şövalyesi"},{"f":"assets/tagimg/5ef9961ab948.webp?v=68101ea3e3","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Vahidan Engizisyoncuları":{"t":"f","sub":"Vahidan Kilisesi’nin Inquisitor’ları","bio":["Vahidan Kilisesi’ne bağlı engizisyoncular: Damriel, Loydelius, Rahal ve Tarnum."],"alias":["Inquisitor’lar","Inquisitor'lar","Inquisitorlar","Damriel","Loydelius","Rahal","Tarnum","Inquisitor Damriel","Inquisitor Loydelius","Inquisitor Rahal","Inquisitor Tarnum"],"ph":[{"f":"assets/tagimg/503bce2658e4.webp?v=607d399162","w":785,"h":1400,"cap":"Inquisitor Damriel"},{"f":"assets/tagimg/2e6e32409ec4.webp?v=dbcd1fe3ce","w":939,"h":1400,"cap":"Inquisitor Loydelius"},{"f":"assets/tagimg/2d5ec852fbf4.webp?v=902838b1cb","w":736,"h":1104,"cap":"Inquisitor Rahal"},{"f":"assets/tagimg/5bbc3977909c.webp?v=e66be3df86","w":700,"h":1400,"cap":"Inquisitor Tarnum"}]},"Prens Michael":{"t":"c","sub":"Batıya keşfe çıkan prens","bio":["Narnold hanedanından bir prens. Coğrafi keşifler için Balahnur’dan batıya yola çıktı; çok uzak batıda devasa bir kıta buldu ve imparatorluk ordularıyla birlikte zenginliklerle Balahnur’a döndü.","Dönüşle aynı dönemde Inu dönüşümleri başladı ve başta getirilen meyvelere bağlandı; bu bağlantının yanlış olduğu sonradan anlaşıldı. Inu laneti, Girift Alem ve cadılar bu seferle bağlantılıdır; ekip bunu çözmeye çalışıyor.","Şirketler kaydına göre Benjamin Lethaniel ile birlikte IN-co’nun (Imperial Navy) sahibidir: görünürde ev aletleri ve sivil gemicilik, asıl işi donanma gemileri."],"facts":[["Hanedan","Narnold"],["Şirket","IN-co (Imperial Navy)"]],"alias":["Michael Narnold","Prens Michael Narnold"],"ph":[{"f":"assets/tagimg/89942051b267.webp?v=393e1ae966","w":933,"h":1400,"cap":"Prens Michael"},{"f":"assets/tagimg/1b87370496ec.webp?v=c83d629938","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Prens Ezreal":{"t":"c","sub":"Dritorial Collegium’un başı · gölge büyüsü","bio":["Narnold hanedanından, Balahnur’da kalan prens. Gölge büyüsü (shadow magic) bilir.","İmparatorluğun istihbarat teşkilatı sayılan Dritorial Collegium’un başındadır. Cücelerin Kutsal Elmayı kopyalamasını engelledi ve şirketleri takip ediyordu.","Balahnur’un düşüşünde imparatorluğun son savunması olarak şehirde cadılarla kalan prens; gizli silahı Indomitable Prime’dır."],"facts":[["Hanedan","Narnold"],["Teşkilat","Dritorial Collegium"],["Büyü","Gölge büyüsü"]],"alias":["Ezreal","Ezreal Narnold","Prens Ezreal Narnold"],"ph":[{"f":"assets/tagimg/4c1607e18c1f.webp?v=5b84adac9d","w":912,"h":1364,"cap":"Prens Ezreal"},{"f":"assets/tagimg/83d7db39aa8f.webp?v=5224d7d816","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Dritorial Collegium":{"t":"f","sub":"İmparatorluğun istihbarat teşkilatı","bio":["Görünürde haritalar, han ve ulaşım hizmetleri sunan bir şirket; asıl işi casusluk, casusluk aletleri ve gizlilik büyüleri.","Sahipleri kartograf ve sistem mimarı Quentin Verhoeven ile Prens Ezreal Narnold’dur; Prens Ezreal teşkilatın başındadır."],"ph":[{"f":"assets/tagimg/598a7b337761.webp?v=5380e9b31e","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Abdiel":{"t":"c","sub":"Kutsal Elma’nın koruyucu şövalyesi","bio":["Kutsal Elma’yı taşıyan koruyucu şövalye. 2117’de Keskinayazlarla savaşırken öldü; Keskinayazların hedefi elma olmadığı için Kutsal Elma yeryüzünde bir buzun içinde kaldı."],"ph":[{"f":"assets/tagimg/6a12c44e6fe4.webp?v=31b21a0b36","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Aday 832":{"t":"c","sub":"Crownforge şövalye adayı","bio":["Project Crownforge’un yedi haftalık programındaki şövalye adaylarından biri; programın anlatısı 832 numaralı adayın gözünden ilerler. Program sonunda 104 adaydan 52’si şövalye ilan edildi."],"facts":[["Program","Project Crownforge"]],"ph":[{"f":"assets/tagimg/5b0a376a57e5.webp?v=f131e5b945","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Amanar":{"t":"c","sub":"Derinlerden gelen deniz yaratığı","bio":["Derinlerden gelen dev bir deniz yaratığı. 7036’da III. Hobbit Krallığı’nı yok etti, yüzlerce Hobbit’i yuttu ve bir daha görülmedi.","Balahnur’un tahliye gecesi korsanlarla birlikte yeniden saldırdı; limanın suyu Amanar’ın sırtıyla ikiye ayrıldı."],"facts":[["Tür","Dev deniz yaratığı"]],"ph":[{"f":"assets/tagimg/6c151df4b67c.webp?v=5bf1b3f4f9","w":610,"h":814,"cap":"Amanar"},{"f":"assets/tagimg/60d6d37f8ddc.webp?v=410befc0cc","w":1400,"h":786,"cap":"Tahliye gecesi Balahnur limanında"}]},"Ark Armatech işçileri":{"t":"f","sub":"Ark Armatech çalışanları","bio":["Aldric’in şirketi Ark Armatech’in çalışanları; aralarında Aldric’in satın aldığı kobold işçiler de vardı. Balahnur düşerken Aldric onlara barikat görevleri verdi.","İşçilerin çoğu ayin gecesinden beri hayvana dönüşmeye başlamıştı; tahliye sırasında “yarısı hayvan formundaydı”."],"ph":[{"f":"assets/tagimg/f8a96ca6befa.webp?v=c495b373af","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Balahnur halkı":{"t":"f","sub":"Balahnur’un sakinleri","bio":["Balahnur şehrinin halkı. Hayvan laneti zamanla herkese yayıldı; dönüşümün başlama ve kalıcılaşma zamanı kişiden kişiye değişti.","Tahliye gecesi Balahnur’dan yaklaşık 500 bin kişi cüce tünelleri ve elf kapılarından geçirilerek kurtarıldı."],"ph":[{"f":"assets/tagimg/acce036e27a3.webp?v=5f255bf743","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Beyaz saçlı cadı":{"t":"c","sub":"Girift Alem’deki beyaz saçlı kadın","bio":["Aldric’in Girift Alem’e ilk yolculuğunda, güneş tutulması olan bir sahilde gördüğü beyaz saçlı kadın; ikinci görüşte ellerinden kan akıyordu.","Crownforge ayininde İmparatoriçe’yi ve Kutsal Elma’yı kaçıran kişi olarak geçer."],"alias":["Beyaz saçlı kadın"],"ph":[{"f":"assets/tagimg/7957806e94f5.webp?v=65a6eec048","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Blanka":{"t":"c","sub":"Blanka Herkenoff","bio":["Reiner Herkenoff’un eşi ve Herkenoff şirketinin halka görünen yüzü. Eskiden imparatorluğun Orman Muhafızı Komutanı’ydı; Reiner onu vampir esaretinden kurtarmıştı.","Herkenoff malikânesi baskınında Gideon ile dövüştü."],"alias":["Blanka Herkenoff"],"ph":[{"f":"assets/tagimg/0615880d073c.webp?v=d4347ce30e","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Fenzo Verrori":{"t":"c","sub":"Veridus pilotu","bio":["Chavel yarışlarında kırmızı arabalı Veridus pilotu. İki atlı aracında fazladan tekerlekler ve çok iyi mühendisler vardı; Aldric ilk kez kendisinden tehlikeli derecede ileri bir mühendisliğe onun aracında tanık oldu.","F2 dayanıklılık yarışında Ayrton’un rakipleri arasında geçen “Penzo Verrori” ile aynı kişi olabilir; bu kayıtlarda kesin değildir."],"alias":["Penzo Verrori"],"ph":[{"f":"assets/tagimg/d8248cc2b016.webp?v=12d17a6aba","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Gonman":{"t":"c","sub":"Kayaçene klanının reisi","bio":["Kayaçene cüce klanının reisi. 4635’te Kayaçene kendi tanrılarını ilan edince diğer klanlar savaş açtı; Gonman klanın kalesini ölene dek savundu. Hiç Kayaçeneli kalmadığı hâlde cesedi bulunamadı."],"ph":[{"f":"assets/tagimg/709d9a518168.webp?v=0e9e47b5ef","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Ivar Mannavegr":{"t":"c","sub":"Kuzeyli denizci yağmacı","bio":["Kuzeyli bir denizci. 9411’den itibaren kendi filosunu toplayıp okyanusa kıyısı olan her devlete yağma saldırıları yaptı ve yakalanana dek korku saldı. 9436’da ortadan kayboldu."],"ph":[{"f":"assets/tagimg/8ff7db55464a.webp?v=16b4c07e0f","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Jessie":{"t":"c","sub":"Evin eski sahibi","bio":["Aldric’in Asgar Üniversitesi üzerinden izine düştüğü kişilerden. Aldric’in aldığı evin önceki sahibi; evde sonradan vampir Vagor yaşıyordu."],"ph":[{"f":"assets/tagimg/c05de71e43b7.webp?v=2b79909801","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Jörmunngandr":{"t":"c","sub":"Jörmünder cüce klanıyla anılan varlık","bio":["5707 kaydında yalnızca başlık olarak geçer: “Jörmunngandr’ın ölümü ve Jörmünder cüce klanının kökenleri”.","Kayıtlarda ayrıntı yok; adının benzerliğinden Jörmünder cüce klanının adını ondan aldığı tahmin ediliyor; ne tür bir varlık olduğu yazılı değil."],"ph":[{"f":"assets/tagimg/d64f15786b6b.webp?v=2c4f7beff3","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Magmadilli Gikhon":{"t":"c","sub":"Lüangraftbötr klanının reisi","bio":["Lüangraftbötr cüce klanının reisi. 5322’de Gimbatul’un kurulmasını istemeyerek Arowuhl Elf kralı Mythanar Reykalyn’e saldırdı (Dwarrebanih Savaşı); elf okçuları ve anka kuşları karşısında yenildi."],"ph":[{"f":"assets/tagimg/388eb5f96450.webp?v=7c4dfa6c07","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Margrave":{"t":"c","sub":"Margrave Hexenkommissar","bio":["Hexenkommissar rütbelerinden Margrave: bölge operasyonlarını yürütür, tutuklama ve infaz yetkisi vardır, imparatorluktan savaş makinesi, paladin ve gemi talep edebilir.","Kar ve Beaver Street isyanı gününde Gideon’u daha büyük bir kariyere özendirmeye çalıştı; Gideon alyansını gösterip “Ben burada Daria’yla mutluyum” dedi."],"facts":[["Rütbe","Margrave Hexenkommissar"]],"ph":[{"f":"assets/tagimg/7f78e391d2b9.webp?v=1f6f50381c","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Milo":{"t":"c","sub":"Jonas Bell’in oğlu","bio":["Kurt adam Jonas Bell’in oğlu. Ateşi düşmeyen, kan kusan bir hastaydı; pelerinli adam babasına onu kurtarabileceğini söyledi ve Milo iyileşti. Vaka kapanınca Gideon onun için karakolda yer ayarladı."],"ph":[{"f":"assets/tagimg/8355cb1bd638.webp?v=181d060444","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Narnold":{"t":"c","sub":"Kutsal Elma taşıyıcısı · İmparatorluğun kurucusu","bio":["Kutsal Elma’nın taşıyıcısı. Saklı Prens Savaşı’nda (9447–9450) komutayı aldı, savaşı kazanıp insan krallıklarını birleştirdi ve İmparatorluğu kurdu.","Narnold soyunun kökeni 8102’de kurulan Blavinken’dir; Prens Michael ve Prens Ezreal bu hanedandandır."],"alias":["Narnold (soyu)","Narnold soyu","Narnold hanedanı"],"ph":[{"f":"assets/tagimg/06a98ebbffa8.webp?v=35cb835b42","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Nerissa":{"t":"c","sub":"Julius’un loncası","bio":["Julius’un Mital Alari’deki loncasının üyesi; Julius’un Nyxara’nın mağarasına götürdüğü altı üyeden biriydi."],"ph":[{"f":"assets/tagimg/6f1153c75e13.webp?v=bfc4c8dcff","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Prens Askar":{"t":"c","sub":"Balahnur’un genç prensi","bio":["Balahnur Krallığı’nın prensi; soyu 7822’de kurulan Balahnur’a dayanır. Pullar (9438), Yakut Beyi (9439), Suskun Diyar (9440), Donmuş Kan (9442) ve Bereket Nehri (9443) savaşlarını kazandı.","Saklı Prens Savaşı sırasında üç yıldır ölü olduğu ve savaşı karısının yönettiği ortaya çıktı; halk karısını linç etti."],"alias":["Prens Askar (soyu)","Askar"],"ph":[{"f":"assets/tagimg/6ddd40bd58fd.webp?v=798387e1da","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Pride":{"t":"c","sub":"Gurur Cadısı (günah cadılarından)","bio":["Günah cadılarından biri. Crownforge ayininde meleğin kanatları düşünce onu Balahnur’a yolladı; Aldric kaçmadan önce onunla konuşmayı denedi.","Ayrton’un Pride sinomorph’u ile karıştırılmamalı."],"alias":["Gurur Cadısı","Pride Cadısı"],"ph":[{"f":"assets/tagimg/b0f832bb7683.webp?v=fbdc5f075c","w":1120,"h":1400,"cap":"Pride"},{"f":"assets/tagimg/246d1d1400d2.webp?v=8cfffbed8a","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Qazzeen":{"t":"c","sub":"Kobold lideri","bio":["Kobold lideri. 4172’deki doğal orman yangınını insanların çıkardığını düşündü; 4279’da binlerce Kobold ile insan kabilelerini vassalı yaptı, kütüphanelerini yok edip mucitlerini öldürdü.","4499’da Balahnur bölgesinde altı kabileyi yok ettikten sonra kendi adını taşıyan savaşta bir insan reisi tarafından öldürüldü."],"ph":[{"f":"assets/tagimg/e5963d61cfe9.webp?v=b39ad898ba","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Qibok Pençegöz":{"t":"c","sub":"Köle Koboldların lideri","bio":["9438’de Balahnur Krallığı’ndaki köle Koboldların isyanının lideri. Prens Askar ile savaştı; isyan bastırıldı ve Koboldlar köle olarak kaldı."],"ph":[{"f":"assets/tagimg/e98d74ad7e04.webp?v=a5d72a5312","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Seçilen Işık Elfi kadın":{"t":"c","sub":"Ateşten portala giren elf","bio":["6172’de Işık Elflerinin aralarından seçtiği kadın. Kutsal Elma ile birlikte ateşten portala girdi; portal saatler sonra kapandı, Kutsal Elma Işık Elflerine ulaştı ama kadın geri dönemedi."],"ph":[{"f":"assets/tagimg/f40bfeac3e82.webp?v=7ebab52de6","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Skallagrim Björnulfson":{"t":"c","sub":"Kuzeyin Ejderhası’nı öldüren reis","bio":["Sıradan bir insan oduncuydu. Gimbatul, cüce dağları ve Elf kıtasında yolculuk edip savaşçı olarak döndü; 7199’da kuzeyi barınılmaz hâle getiren ejderhayı tek başına öldürdü ve kabilesini kuzeye taşıdı.","7200’de reis oldu; 7255’teki cenazesi Kuzeyli insanların kökeni sayılır."],"ph":[{"f":"assets/tagimg/993fd8c959d0.webp?v=7503d84387","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Stefen":{"t":"c","sub":"Kapsülü tanıyan bilgin","bio":["Aldric’in Asgar Üniversitesi üzerinden izine düştüğü kişi. Ekipteki kapsülün antik Güney İmparatorluğu’na (Ankabar Jinkarin) ait bir bilgelik kapsülü olduğunu anlattı ve haritada imparatorluğun yerini gösterdi.","Kayıtlarda ayrıntı yok; Jephcoats’un mektubunda Ebon Passage’daki evi geçen “Stephen” ile aynı kişi olduğu düşünülüyor."],"alias":["Stephen"],"ph":[{"f":"assets/tagimg/10ba98d7a3d6.webp?v=69011fd038","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Wolbodo":{"t":"c","sub":"I. Hobbit Krallığı’nın kralı","bio":["I. Hobbit Krallığı’nın kralı. 3382’de krallığın 1. yılını kutlarken altınların çoğunu halka dağıttı; altın hastalığı yayıldı ve Zaaf Naraları gecesinde krallık yıkıldı."],"ph":[{"f":"assets/tagimg/b455250cdffb.webp?v=9f01ec35d8","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Ægnádr":{"t":"c","sub":"Arowuhl şelalesini açan dev","bio":["3426’da taşan göl ve nehirleri görünce toprağı elleriyle yararak suya yol açan dev. Dev dilinde dua edip şelaleye üfledi: “Bin yıllar boyunca bu şelale şeklini değiştirmesin, kimseye zarar vermesin.”"],"alias":["Aegnadr"],"ph":[{"f":"assets/tagimg/18685a0c88dc.webp?v=b61adbffbd","w":1280,"h":720,"cap":"Temsilî çizim"}]},"İmparatorluk ordusu":{"t":"f","sub":"İmparatorluğun orduları","bio":["Batı seferinden prensle birlikte zenginliklerle dönen imparatorluk orduları. Inu dönüşümleri başlayınca imparatorluk görülen Inu’ları infaz etmeye başladı.","Balahnur düşerken eski imparatorluk taburlarının bir kısmı Oburluk Cadısı’nın kontrolüne geçti."],"ph":[{"f":"assets/tagimg/fbdf0a63e477.webp?v=6ed7848030","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Antik kule":{"t":"p","sub":"Güney kıyısındaki büyülü kule","bio":["Güney seferinde kıyıdaki deniz feneri benzeri antik kule; Aetherion Magnus’a büyü ateşi açıp balonu vurdu. Dibinde ortası delinmiş gemi enkazları vardı."],"ph":[{"f":"assets/tagimg/54e2570cd1f5.webp?v=21e5792b80","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Arkwright evi":{"t":"p","sub":"Aldric’in ailesinin evi","bio":["Aldric’in çocukluk evi. Aldric sekiz yaşındayken ailesi burada öldürüldü; gardırobun aralığından katilin parmağındaki T harfli yüzüğü gördü. Arkwright Hanesi nesillerdir silah üreten bir ailedir."],"ph":[{"f":"assets/tagimg/a10cb90befba.webp?v=e791397be2","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Ateşten portal":{"t":"p","sub":"Dev banyosu denizinin üstündeki portal","bio":["6089’da yanardağlardan yükselen lavların Dev banyosu denizinin üstünde toplanmasıyla oluşan ateşten portal. Güneş Savaşları’nda kızıl yaratıklar buradan çıktı; 6172’de seçilen Işık Elfi kadın Kutsal Elma ile buraya girdi ve portal kapandı."],"ph":[{"f":"assets/tagimg/0594693a716b.webp?v=1f73109a99","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Ayrton'un malikânesi":{"t":"p","sub":"Ayrton’un evi","bio":["Ayrton’un malikânesi. Narnia yarışından önce Dolunay Çetesi’nin lideri burayı işgal etti; festival günlerinde goblinler ateşe verdi."],"ph":[{"f":"assets/tagimg/81bf70bcce32.webp?v=f61d552b2d","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Ayrton'un zihni":{"t":"p","sub":"Sinomorph’ların iç dünyası","bio":["Ayrton’un sinomorph’larının yaşadığı iç dünya. Mutagen sınırı aşılınca Pride tam tezahür edip diğer günahları susturdu ve Ayrton günlerce zihninde hapis kaldı; Omux orada ona yardım etti."],"ph":[{"f":"assets/tagimg/9e7b3436384e.webp?v=d4342293ed","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Balahnur kanalizasyonları":{"t":"p","sub":"Şehrin altındaki tüneller","bio":["Balahnur’un kanalizasyon ağı. Kaçak tünellerinden Tabaat İsmail’in karaborsa erzak düzeni yürüyordu.","Balahnur düşerken Gideon yaralıları ve çocukları yanan sokaklardan toplayıp buraya indirdi."],"ph":[{"f":"assets/tagimg/8e454c0c9f0c.webp?v=df923cbed7","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Balahnur limanı":{"t":"p","sub":"Balahnur’un limanı","bio":["Balahnur’un limanı. Aetherion Magnus’un yapıldığı dönemde ve Gideon’un odun pazarlığı sırasında (Man o’ War saldırısı) olaylara sahne oldu.","Tahliye gecesi korsanlar ve Amanar limana saldırdı; su Amanar’ın sırtıyla ikiye ayrıldı."],"ph":[{"f":"assets/tagimg/c6bee93edd12.webp?v=410befc0cc","w":1400,"h":786,"cap":"Tahliye gecesi: Amanar limanda"},{"f":"assets/tagimg/29d8aae3c11f.webp?v=bf6750621b","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Balıkçı köyü":{"t":"p","sub":"Blavinken’in güneyinde","bio":["Güney seferinin üçüncü sabahı Aetherion Magnus’un ulaştığı, Blavinken’in güneyindeki balıkçı köyü."],"ph":[{"f":"assets/tagimg/e4da258b14da.webp?v=88da39e5f1","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Bereket Nehri":{"t":"p","sub":"Blavinken’in kuzeyindeki ikiz nehir","bio":["Blavinken’in kuzeyinde ikiz bir nehir; Olik Tarikatı krallığı bunun üstüne kurulmuştu. 9443’te Prens Askar ile bu krallık arasında dinî sebepli savaş burada yaşandı."],"ph":[{"f":"assets/tagimg/caa51efeb4a6.webp?v=03f8c640cf","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Cadıların elindeki taş salon":{"t":"p","sub":"Julius’un tutsak tutulduğu yer","bio":["Julius’un cadıların elinde tutsak tutulduğu taş salon; burada işkence gördü, bir parmağı kesildi ve günlerce şarkı söylemeye zorlandı.","Kayıtlarda ayrıntı yok; Aldric Julius’u cadıların ele geçirdiği saraydan aldığı için salonun sarayda olduğu tahmin ediliyor."],"ph":[{"f":"assets/tagimg/337938330a25.webp?v=c905715f3d","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Conjuration okulu":{"t":"p","sub":"Elf kıtasındaki çağırma okulu","bio":["6317’de kurulan Conjuration okulu. 6593’te Elf Conjurer’larının burada yaptığı bir ayinde Elementaller kontrolden çıkıp Elf kıtasına yayıldı."],"ph":[{"f":"assets/tagimg/73e3a93c3830.webp?v=dd4f1e677d","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Coşucuların Hanı":{"t":"p","sub":"Balahnur’da bir han","bio":["Balahnur’daki han. Gideon, Inu’ların burada idam edildiğini söyledi."],"ph":[{"f":"assets/tagimg/221230f5b02a.webp?v=4f441bff13","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Cüce dağları":{"t":"p","sub":"Cüce klanlarının yurdu","bio":["Cüce klanlarının yaşadığı dağlar. Skallagrim’in yolculuğunun ikinci durağıydı; Kabza Gurur ve Kayaçene–Lüangraftbötr savaşları bu klanlar arasında yaşandı."],"ph":[{"f":"assets/tagimg/d48efbb52b3e.webp?v=cea5cc5ce7","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Cüce madenleri":{"t":"p","sub":"Cücelerin madenleri","bio":["Cücelerin madenleri. 2090’da cüceler burada toplanıp Keskinayazlara karşı silahlarda kullanılan bir tılsım dövdü (Sivritılsım Savaşı)."],"ph":[{"f":"assets/tagimg/ada7ef3e585f.webp?v=dc03fbb11b","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Cüce tünelleri":{"t":"p","sub":"Tahliye tünelleri","bio":["Cücelerin Revalor ile birlikte Ark Armatech’in altından şehir dışına kadar kazdığı tünel; ucunda iki portal vardı: cüce başkenti Strombaht ve elflerin uzak kıtadaki boş eski şehri.","Tahliye gecesi insanlar ve sökülmüş Ark Armatech bu tünellerden taşındı."],"alias":["Cüce tüneli"],"ph":[{"f":"assets/tagimg/663eceed3d4d.webp?v=21b6df8118","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Dev banyosu denizi":{"t":"p","sub":"Ateşten portalın oluştuğu deniz","bio":["Kükreyen Dağlar Onyılı’nın 10. yılında yanardağlardan yükselen lavların üstünde toplanıp ateşten portalı oluşturduğu deniz."],"ph":[{"f":"assets/tagimg/7a83ab6f37b8.webp?v=43a85fa77b","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Elf kıtası":{"t":"p","sub":"Elflerin kıtası","bio":["Elflerin kıtası. Işık Elfleri burada ortaya çıktı, hobbitler salgından buraya sığındı; Boraldmir Elf Savaşları ile kıtanın tamamını ele geçirdi."],"ph":[{"f":"assets/tagimg/89e9ee37668e.webp?v=925c06a1a5","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Elf portalı":{"t":"p","sub":"Tahliye kapıları","bio":["Tahliye gecesi elflerin açtığı kapılar; Balahnur’dan kurtarılanların çoğu buradan uzak kıtadaki elf şehri Mital Alari’ye geçti."],"ph":[{"f":"assets/tagimg/b3dc64193fa3.webp?v=3ea8ddd059","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Elf tesisi":{"t":"p","sub":"Aldric’in tutulduğu tesis","bio":["Aldric’in Bitliayak’tan kaçırıldıktan sonra uyandığı beyaz odanın bulunduğu elf tesisi. Burada Ilrune Araxsys ve Arrowhul temsilcisi Kral Revalor’un ona ilgisini belli etti ve omurgasına elf implantları yerleştirildi."],"alias":["Beyaz oda (elf tesisi)","Beyaz oda"],"ph":[{"f":"assets/tagimg/c1d47cb6aba6.webp?v=addfa52d34","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Gideon ile Daria'nın evi":{"t":"p","sub":"Gideon’un evi","bio":["Gideon ile eşi Daria’nın evi; Gideon uzun bir mesainin ardından akşamı Daria ile burada geçirdi."],"ph":[{"f":"assets/tagimg/18dca9c30ed6.webp?v=4d0097c2f5","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Gimbatul'un kuzeyindeki dağlar":{"t":"p","sub":"Kül Katuz Savaşı’nın yeri","bio":["8905’te kuzeydeki insan krallıklarının cüceler elinden almak için savaş açtığı dağlar; cüceler onları Vipreflumen’e kadar kovaladı."],"ph":[{"f":"assets/tagimg/0ae752707e82.webp?v=44017dd0c9","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Herkenoff binası":{"t":"p","sub":"Herkenoff’un Balahnur’daki binası","bio":["Herkenoff ağının Balahnur’daki binası; Ayrton ve Levi Herkenoff’a sızdıkları günlerde buraya girip çıktı."],"ph":[{"f":"assets/tagimg/a4ca97b10111.webp?v=7a2f567018","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Hundred Blades kampı":{"t":"p","sub":"Haydut kampı","bio":["Hundred Blades çetesinin kampı. Julius, Gideon ve Aldric’in desteğiyle haydutların çoğunu katletti ve Anastasia’yı burada buldu."],"ph":[{"f":"assets/tagimg/b49093def17a.webp?v=1f3eba2619","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Hobbit krallıkları":{"t":"p","sub":"I., II. ve III. Hobbit Krallığı","bio":["I. Hobbit Krallığı Singulken civarında kuruldu ve 3382’de Zaaf Naraları gecesinde yıkıldı. II. Hobbit Krallığı 4929’da kuruldu, 5100’de bir salgınla iki yılda yıkıldı.","III. Hobbit Krallığı 6837’de kuruldu; 7036’da Amanar onu yok etti."],"alias":["I. Hobbit Krallığı","II. Hobbit Krallığı","III. Hobbit Krallığı"],"ph":[{"f":"assets/tagimg/d007026cf97f.webp?v=852fd66f8d","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Jephcoats'un evi":{"t":"p","sub":"Profesör Jephcoats’un evi","bio":["Profesör Jephcoats’un evi. Mutfak lavabosunun giderinde küçültme büyüsüyle gizlenmiş bir geçit gizli araştırma odasına iner; içeride False Hydra ve denizanası çizimleri, mektuplar vardı."],"alias":["Jephcoats'un gizli araştırma odası"],"ph":[{"f":"assets/tagimg/9769513b7bac.webp?v=0d772e0673","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Julius'un köyü":{"t":"p","sub":"Julius’un doğduğu köy","bio":["Julius Vane’in köyü. Hundred Blades burayı yaktı; Julius annesinden ve Anastasia’dan ayrı düştü."],"ph":[{"f":"assets/tagimg/27fcc64e7458.webp?v=5fb4177099","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Kobold başkenti":{"t":"p","sub":"Balahnur’dan önceki Kobold başkenti","bio":["Koboldların başkenti. 7818’de II. Khotekx Savaşı’nda Koboldlar teslim olunca yerine Balahnur kuruldu."],"ph":[{"f":"assets/tagimg/595bd862875a.webp?v=a5cb8a7504","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Kobold ormanları":{"t":"p","sub":"Koboldların ormanları","bio":["Koboldların yaşadığı ormanlar. 4012’de Paarthonax buraya uçup kayboldu ve topraklarda bereket arttı; 4172’de büyük bir doğal yangın çıktı."],"alias":["Kobold toprakları"],"ph":[{"f":"assets/tagimg/d70a99f598d7.webp?v=a3ee6c16b7","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Kuzey":{"t":"p","sub":"Horaghfus’un kuzeyi","bio":["Horaghfus’un kuzeyi. Ejderha yüzünden barınılmazdı; 7199’da Skallagrim ejderhayı öldürüp kabilesini buraya taşıdı. 7954’te insan toplulukları kuzeye göçtü, 8559’da Kuzeyli krallıklar kuruldu."],"ph":[{"f":"assets/tagimg/dbd62a2362b6.webp?v=3aeff8d0d6","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Kükreyen Dağlar":{"t":"p","sub":"Yanardağlar","bio":["6089–6099 yılları arasında tüm yanardağların aktifleştiği dağlar (Kükreyen Dağlar Onyılı); lavlar ateşten portalı oluşturdu."],"ph":[{"f":"assets/tagimg/97dedf76886d.webp?v=3392608d84","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Man o' War gemisi":{"t":"p","sub":"İmparatorluk donanmasının gemisi","bio":["Balahnur limanındaki donanmaya ait Man o’ War gemisi. Ambarındaki minotorlar saldırıya geçince Gideon iki muhafızıyla inip onları durdurdu."],"ph":[{"f":"assets/tagimg/86e6dcf1b821.webp?v=e88b6a6f6a","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Nehir":{"t":"p","sub":"Güney adasının büyük nehri","bio":["Güney seferinde antik kule balonu vurunca Aetherion Magnus’un zorunlu iniş yaptığı, adanın merkezine uzanan büyük nehir."],"ph":[{"f":"assets/tagimg/6820171ab8cc.webp?v=7ecd0e1f09","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Okul":{"t":"p","sub":"Balahnur’da bir okul","bio":["River’ın Julius’a, işçi aranan bir etkinlik için gönderdiği okul; Julius burada Amber ile tanıştı."],"ph":[{"f":"assets/tagimg/a8c02f8b1935.webp?v=9b952e0f2b","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Okyanus kıyıları":{"t":"p","sub":"Ivar’ın yağmaladığı kıyılar","bio":["Ivar Mannavegr’in 9411’den itibaren yağmaladığı, okyanusa kıyısı olan devletlerin kıyıları."],"ph":[{"f":"assets/tagimg/89e359a6c078.webp?v=8d8f1cc937","w":1280,"h":720,"cap":"Temsilî çizim"}]},"River'ın ailesinin evi":{"t":"p","sub":"Blavinken ormanındaki donmuş ev","bio":["Blavinken ormanında, River’ın ebeveynlerinin zamanın içinde donduğu ev. Sarkaç bir sonraki vuruşa ulaşamaz, mum alevi titremeyi unutmuştur."],"ph":[{"f":"assets/tagimg/5430911c3e7a.webp?v=37d5013648","w":1400,"h":764,"cap":"Ormandaki ev"},{"f":"assets/tagimg/e718397deb40.webp?v=bf92a684cc","w":1400,"h":788,"cap":"Zamanda donmuş aile"}]},"Saint Antonio kilisesi":{"t":"p","sub":"Balahnur’da bir kilise","bio":["Balahnur düşerken insanların sığındığı kilise. Aldric Vindicator ile buraya gitti; sığınanlar kurtarılıp River’ın portalıyla, önce çocuklar olmak üzere tahliye edildi.","Kayıtlarda Vahidan Kilisesi ile bağlantısı yoktur."],"ph":[{"f":"assets/tagimg/18de4bcaa756.webp?v=8201883dab","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Taverna":{"t":"p","sub":"Balahnur’da bir taverna","bio":["Julius’un Ark Armatech döneminde Amber ile sahne aldığı olaylarla anılan taverna.","Kayıtlarda ayrıntı yok; Balahnur’da, Julius’un çalıştığı çevrede sıradan bir taverna olduğu tahmin ediliyor."],"ph":[{"f":"assets/tagimg/bb7e75eba6bb.webp?v=44ff1941b0","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Tutulma sahili":{"t":"p","sub":"Girift Alem’deki sahil","bio":["Girift Alem’de güneş tutulması olan sahil. Aldric burada beyaz saçlı kadını gördü; cadılar Inu olayını bu tutulma yerinde araştırmak istiyordu."],"ph":[{"f":"assets/tagimg/992b2560684c.webp?v=3a57b4d97d","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Vipreflumen":{"t":"p","sub":"Kuzeyde bir bölge","bio":["Kül Katuz Savaşı’nda (8905) cücelerin kuzeyli insanları kovaladığı yer; 9444’te adını taşıyan bir savaş yaşandı (yalnızca başlık olarak kayıtlı)."],"ph":[{"f":"assets/tagimg/354c62f467d7.webp?v=df6132da8c","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Yakutlar":{"t":"p","sub":"Gimbatul’un batısındaki bölge","bio":["8730’da kuruldu. Gimbatul’un batısında, stratejik bir bölgedeki Yakutlar 9439’da Yakut Beyi Savaşı’nda Prens Askar’a yenildi."],"ph":[{"f":"assets/tagimg/fb232a9f5299.webp?v=0a6f0ae3bd","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Yeraltı tünelleri":{"t":"p","sub":"Kanunsuz Dönem’in sığınakları","bio":["Keder Yağışları döneminde yeryüzünde yaşayamayan ırkların sığındığı tüneller ve oyuklar. 3000’de büyük deprem tüneldekileri dışarı kaçırdı ve yeryüzünün yeniden yaşanabilir olduğu anlaşıldı."],"ph":[{"f":"assets/tagimg/147bd3440194.webp?v=31ed168e36","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Yuvarlak Masa Yolu":{"t":"p","sub":"9432’de kurulan yol","bio":["Kronolojide yalnızca başlık olarak geçer: “9432 Yuvarlak Masa Yolu’nun kurulması”.","Kayıtlarda ayrıntı yok; adından bir yol, yol ağı ya da bir topluluk olduğu tahmin ediliyor."],"ph":[{"f":"assets/tagimg/0da2515cef7f.webp?v=43daa3ac28","w":1280,"h":720,"cap":"Temsilî çizim"}]},"İmparatorluk sarayı":{"t":"p","sub":"Balahnur’daki saray","bio":["Balahnur’daki imparatorluk sarayı. Balahnur düşerken cadılar sarayı ele geçirdi; Aldric Julius’u takas etmek için buraya gitti."],"ph":[{"f":"assets/tagimg/d15dd50ccffc.webp?v=e5d41b8b3e","w":1280,"h":720,"cap":"Temsilî çizim"}]},"İmparatorluk şehirleri":{"t":"p","sub":"İmparatorluğun şehirleri","bio":["Büyük Savaş kazanıldıktan sonra kutlamaların başladığı imparatorluk şehirleri: sokaklara bayraklar asıldı, tüccarlar yollara döndü."],"ph":[{"f":"assets/tagimg/90b3134e43ff.webp?v=b0886ac9f2","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Arowuhl şelalesi":{"t":"p","sub":"Ægnádr’ın şelalesi","bio":["3426’da dev Ægnádr’ın toprağı elleriyle yarıp taşan sulara yol açmasıyla oluşan şelale. Dev, şelalenin bin yıllar boyunca şeklini değiştirmemesi ve kimseye zarar vermemesi için dua edip üfledi."],"ph":[{"f":"assets/tagimg/e2e8e456bc8d.webp?v=899e86b9f6","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Antik Güney İmparatorluğu":{"t":"f","sub":"An’kabar Jihkari’nin imparatorluğu","bio":["Güneyli medeniyetlerin imparatorluğu; hükümdarlarına An’kabar denir. 1949’da Kadim Tanrılar Tarikatı’nı kurdu, 1961’de elflere saldırıp kaybetti; 2021’de kar yağışıyla çöktü ve son Tiefling hükümdar dokuzgen yapıyı kendine mezar yaptı.","Ölümsüz kâtip Pirdeviz bu sarayın kâtibiydi; ekipteki bilgelik kapsülü bu imparatorluğa aittir. Toprakları artık elf toprağıdır."],"alias":["Antik Güney İmparatorluğu (Ankabar)","Güneyliler","Tiefling hanedanı","Güney İmparatorluğu"],"ph":[{"f":"assets/tagimg/b7b7dea329c7.webp?v=8d552f74e1","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Arkwright Hanesi":{"t":"f","sub":"Aldric’in ailesi","bio":["Nesillerdir silah üreten aile; Aldric Vorn Arkwright bu haneden gelir. Aldric sekiz yaşındayken ailesi evlerinde öldürüldü; katilin yüzüğü bir Barışbozan’a aitti."],"ph":[{"f":"assets/tagimg/3bf9b9c454ae.webp?v=92e52b8d36","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Arowuhl Elfleri":{"t":"f","sub":"Arowuhl’un elfleri","bio":["3499’da kurulan Arowuhl krallığının elfleri. Kralları Mythanar Reykalyn Gimbatul’u kurdu ve Dwarrebanih Savaşı’nı kazandı; 7489’da kıtlık lanetini kaldırdılar."],"ph":[{"f":"assets/tagimg/036186c51178.webp?v=8f774d8155","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Balahnur Krallığı":{"t":"f","sub":"Balahnur’un krallığı","bio":["7822’de kurulan krallık; Prens Askar’ın soyunun kökenidir. Köle Koboldlar 9438’de bu krallıkta isyan etti."],"ph":[{"f":"assets/tagimg/e28ee1c0b038.webp?v=70594e8a74","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Boraldmir soyu":{"t":"f","sub":"Boraldmir’in hanedanı","bio":["Elf hükümdarı Boraldmir’in hanedanı. 9455’teki insan mülteci krizinde insanları ülkelerine kabul etti; Reneagor Sin Boraldmir bu karara karşı çıktı."],"ph":[{"f":"assets/tagimg/9127252054ba.webp?v=4307d5df82","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Boraldmir'in müttefikleri":{"t":"f","sub":"Elf Savaşları’ndaki taraf","bio":["Elf Savaşları’nda (9598–9734) Boraldmir’in yanında yer alan elf krallıkları. Savaşlar ve entrikalarla Boraldmir kıtanın tamamını ele geçirdi."],"ph":[{"f":"assets/tagimg/89b32e6ed4a6.webp?v=65d39290ec","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Bronzçınar klanı":{"t":"f","sub":"Cüce klanı","bio":["Cüce klanı. 7671’de festival yarışında sırası Strömbah klanınca çalınınca Kabza Gurur Savaşı çıktı; 9577’de Akan Kazan Savaşı’nda cüceleri temsil etti."],"ph":[{"f":"assets/tagimg/79b78c94dd3c.webp?v=2436c142ef","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Büyücüler":{"t":"f","sub":"Horaghfus’un büyücüleri","bio":["9737’de Horaghfuslu büyücüler güçlerinin tükenmediğini, büyü için dinlenmeleri gerekmediğini fark etti (Büyü Kusulması). Krallıklar 9763’te onlarla Nasihir Akademisi’ni kurdu; 9778’de akademi dağıldı."],"ph":[{"f":"assets/tagimg/e96791689a28.webp?v=015cbd8fa4","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Cüceler":{"t":"f","sub":"Cüce ırkı","bio":["Horaghfus’un cüce ırkı. Keder Yağışları’nda Keskinayazlara karşı tılsım dövdüler, Manayutanlardan Strömbah dağına kaçıp Dempur madenini kurdular; 3764’te klanlar birleşti.","Balahnur düşerken Revalor ile şehir dışına tünel kazıp tahliyeyi mümkün kıldılar."],"alias":["Cüce klanları","Cüce madenciler"],"ph":[{"f":"assets/tagimg/3532b685f5ea.webp?v=b880cc6558","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Devler":{"t":"f","sub":"Dev ırkı","bio":["Devler. Kayıtlı tek olayda dev Ægnádr Arowuhl şelalesini açtı."],"ph":[{"f":"assets/tagimg/e19adb5e79c2.webp?v=963e381e7e","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Druidler":{"t":"f","sub":"Doğa koruyucuları","bio":["1981’deki 20 Yıllık Kuraklık boyunca Entlerle birlikte yeşil hayatı korumaya çalışan druidler."],"ph":[{"f":"assets/tagimg/75b879131882.webp?v=9c18784af2","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Entler":{"t":"f","sub":"Ağaç varlıklar","bio":["1981’deki 20 Yıllık Kuraklık boyunca Druidlerle birlikte yeşil hayatı korumaya çalışan Entler."],"ph":[{"f":"assets/tagimg/d9a781b4b10e.webp?v=5970542a8d","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Elementaller":{"t":"f","sub":"Çağrılmış varlıklar","bio":["6593’te Elf Conjurer’larının ayininde kontrolden çıkıp Elf kıtasına yayılan Elementaller; biri Elemental üretmeyi öğrendi. 6600’de elflerle Çağrılmış Savaş’ı yaptılar."],"ph":[{"f":"assets/tagimg/eea37737a025.webp?v=d57f3eb322","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Elf Conjurer'ları":{"t":"f","sub":"Elf çağırıcı büyücüleri","bio":["Conjuration okulundaki elf büyücüleri; 6593’teki ayinlerinde Elementaller kontrolden çıktı (Elementhaff’adt Vakası)."],"ph":[{"f":"assets/tagimg/284c10036622.webp?v=6356f20dc3","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Elfler":{"t":"f","sub":"Elf ırkı","bio":["Horaghfus’un elf ırkı. 1961’de Güneylilerin saldırısını püskürttüler, 2066’da Manayutanlar karşısında krallıkları düştü. Elf Savaşları’nda Boraldmir kıtanın tamamını ele geçirdi.","Büyük Savaş’ta Revalor Olawarin üç ırkı birleştirdi; tahliye gecesi elfler Balahnur halkı için kapılar açtı."],"alias":["Elf krallıkları","Diğer elf krallıkları"],"ph":[{"f":"assets/tagimg/c16ceb8d8e9e.webp?v=186a08829a","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Elf teologları":{"t":"f","sub":"Elf din bilginleri","bio":["Kükreyen Dağlar Onyılı’nda ateşten portal oluşunca bazı elf teologları antik tanrılardan birinin geri döndüğünü düşündü."],"ph":[{"f":"assets/tagimg/6d7f16ba4703.webp?v=76134b2f56","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Gimbatullu Elfler":{"t":"f","sub":"Gimbatul’un elfleri","bio":["Gimbatul’un elfleri. Kabza Gurur Savaşı’nın sonunda cüce klanları sınırı geçtiklerini sanıp onlara saldırınca bunun bir yanlış anlaşılma olduğunu söyleyip özür dilediler."],"ph":[{"f":"assets/tagimg/0e75f2cda052.webp?v=e88b267b4d","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Goblinler":{"t":"f","sub":"Goblin ırkı","bio":["6836’da Elf kıtasındaki Hobbitleri kaçırdılar; elflerin silah desteğiyle Hobbitler onları bölgeden kovdu.","Festival günlerinde Ayrton’un malikânesini ateşe verdiler. Phoenix’in hatırladığı kadarıyla Gideon ile Ayrton Güney seferinden önce gidip goblinlere saldırdı."],"ph":[{"f":"assets/tagimg/ac0534b3af37.webp?v=7ec598caec","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Güneyli Elfler":{"t":"f","sub":"Güneydeki elfler","bio":["Horaghfus Savaşı’nda Boraldmir’in fethettiği güneydeki elfler; Akan Kazan Savaşı yüzünden kimse yardımlarına gitmedi."],"ph":[{"f":"assets/tagimg/e507a58830d4.webp?v=c357e5ab38","w":1280,"h":720,"cap":"Temsilî çizim"}]},"High Elfler":{"t":"f","sub":"Yüksek elfler","bio":["High Elfler. 2370’te yeni büyüler ararken aralarından ışık büyüsü yapabilenler keşfedildi; böylece Işık Elfleri ortaya çıktı."],"ph":[{"f":"assets/tagimg/4f94c1744902.webp?v=8ec42f7d67","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Orman Elfleri":{"t":"f","sub":"Ormanların elfleri","bio":["Orman Elfleri; Işık Elfleriyle birlikte çalışarak güneşsiz dönemde tarımı mümkün kıldılar."],"ph":[{"f":"assets/tagimg/b5ebd5809604.webp?v=e04f83c5d8","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Işık Elfleri":{"t":"f","sub":"Işık büyüsü yapan elfler","bio":["2370’te High Elflerden ayrıldıkları keşfedilen, ışık büyüsü yapabilen elfler; Orman Elfleriyle tarımı mümkün kıldılar. Güneş Savaşları’nda kızıl yaratıkları savuşturdular.","9735’te Işık Elfleri Orc’a dönüştürüldü (yalnızca başlık olarak kayıtlı)."],"ph":[{"f":"assets/tagimg/c55fec43c5ee.webp?v=c1909bdb14","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Hobbitler":{"t":"f","sub":"Hobbit ırkı","bio":["Üç kez krallık kurdular: I. (Zaaf Naraları’nda yıkıldı), II. (salgınla yıkıldı) ve III. (Amanar yok etti). 7489’da bir hobbitin cine dilediği dilek Delik Varil Kıtlığı’na yol açtı."],"ph":[{"f":"assets/tagimg/d7562716c0c0.webp?v=a759f66b5a","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Horaghfus asilleri":{"t":"f","sub":"Soylu aileler ve krallar","bio":["Horaghfus’un soylu aileleri ve kralları. 1951’de Ölüm her soylu krala bir taş verdi; 2799 Manayutan baskınlarında taş verilen asiller öldükten sonra geri döndü ve asil aile sayısı azaldı."],"alias":["Horaghfus asil aileleri","Soylu krallar"],"ph":[{"f":"assets/tagimg/a29a6730977d.webp?v=41e2befd7d","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Horaghfus ırkları":{"t":"f","sub":"Horaghfus’un tüm halkları","bio":["Horaghfus’un tüm ırk ve krallıkları. Keder Yağışları hepsini vurdu; 3000’de yeryüzü yaşanabilir olunca hepsi Manayutanlarla savaştı ve 3050’de Manayutanların soyu tükendi."],"alias":["Tüm krallıklar","Horaghfuslu krallıklar"],"ph":[{"f":"assets/tagimg/f02644ed354e.webp?v=2d9de30e91","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Jörmünder cüce klanı":{"t":"f","sub":"Cüce klanı","bio":["5707 kaydında kökenleri Jörmunngandr’ın ölümüyle birlikte anılan cüce klanı; ayrıntı yazılı değil."],"ph":[{"f":"assets/tagimg/f551180c117a.webp?v=e567de03dd","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Kadim Tanrılar Tarikatı":{"t":"f","sub":"An’kabar’ın kurdurduğu tarikat","bio":["1949’da An’kabar Jihkari’nin emriyle kurulan çok ırklı tarikat; Kadim Tanrıları geri getirmek için yükseldikçe daralan dokuzgen bir yapıda ayin yaptı. Rahipler “Doğuya!” cevabını aldıktan kısa süre sonra öldü."],"ph":[{"f":"assets/tagimg/051a0b7e50be.webp?v=fd452754c8","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Kayaçene klanı":{"t":"f","sub":"6. cüce klanı","bio":["6. cüce klanı. 4635’te kendi tanrılarını ilan edince diğer klanlar savaş açtı; reisleri Gonman kaleyi ölene dek savundu ve hiç Kayaçeneli kalmadı."],"ph":[{"f":"assets/tagimg/f8ec0065980f.webp?v=052444cd45","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Koboldlar":{"t":"f","sub":"Kobold ırkı","bio":["Kobold ırkı. Qazzeen önderliğinde insan kabilelerini vassalı yaptılar; 7815–7818 Khotekx savaşlarında yenilip teslim oldular ve başkentlerinin yerine Balahnur kuruldu.","Balahnur Krallığı’nda köle olarak tutuldular (9438 Pullar Savaşı); Aldric Ark Armatech için kobold işçiler satın aldı."],"alias":["Köle Koboldlar"],"ph":[{"f":"assets/tagimg/b2c364653a89.webp?v=2059028879","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Korsanlar":{"t":"f","sub":"Tahliye gecesi saldıranlar","bio":["Balahnur’un tahliye gecesi Amanar ile birlikte limana saldıran korsanlar.","Kayıtlarda ayrıntı yok; Revalor’un anlattığı “güneyde dev bir deniz yaratığına sahip, antik elf elementallerini toplayan korsan” ile bağlantılı oldukları tahmin ediliyor."],"ph":[{"f":"assets/tagimg/5f7775719da0.webp?v=4223ed0d41","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Kuzeyli insanlar":{"t":"f","sub":"Kuzeyin insanları","bio":["Kuzeyli insanların kökeni 7255’te Skallagrim Björnulfson’un cenazesine dayanır. Kuzey kabileleri, Skallagrim ejderhayı öldürünce kuzeye taşındı; 7954’te insan toplulukları kuzeye göçtü.","Kuzeyli denizci Ivar Mannavegr okyanus kıyılarını yağmaladı."],"alias":["Kuzey kabileleri","İnsan toplulukları","Kuzeyli denizciler"],"ph":[{"f":"assets/tagimg/85bc09439d82.webp?v=29e3d81c6a","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Kuzey İttifakı":{"t":"f","sub":"Kuzeyli krallıkların ittifakı","bio":["8900’de kuruldu. 8905’te Gimbatul’un kuzeyindeki dağları almak için cücelere savaş açtı (Kül Katuz Savaşı), yenildi ve aynı yıl bozuldu."],"ph":[{"f":"assets/tagimg/d8803a526a29.webp?v=cb081f5162","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Kuzeyli krallıklar":{"t":"f","sub":"Kuzeyin insan krallıkları","bio":["8559’da kuruldular. Kül Katuz Savaşı’ndan sonra cüce klanlarının üstünlüğünü kabul ettiler; Saklı Prens Savaşı’nda Balahnur’la savaştılar."],"alias":["Kuzey krallıkları"],"ph":[{"f":"assets/tagimg/31215cd6f797.webp?v=2630dba743","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Kızıl yaratıklar":{"t":"f","sub":"Ateşten portalın yaratıkları","bio":["6099’dan itibaren ateşten portaldan dalga dalga çıkan, ateşten ve kara büyüden etkilenmeyen kızıl yaratıklar; Işık Elfleri hepsini savuşturdu."],"ph":[{"f":"assets/tagimg/e0d1f7d5357e.webp?v=7ed3dddfb5","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Lüangraftbötr cüce klanı":{"t":"f","sub":"Cüce klanı","bio":["Cüce klanı. 4635’te diğer klanlarla Kayaçene’ye savaş açtı; reisi Magmadilli Gikhon 5322’de Dwarrebanih Savaşı’nda Mythanar Reykalyn’e yenildi."],"alias":["Lüangraftbötr ve diğer cüce klanları","Lüangraftbötr"],"ph":[{"f":"assets/tagimg/26941d7757d0.webp?v=588bc78ee1","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Manayutanlar":{"t":"f","sub":"Büyü emen yaratıklar","bio":["2059’da yokluktan çıkan altı kollu, dört ayaklı, büyük ağızlı yaratıklar; derileri büyüyle üretilmiş her şeyi emiyordu. Elf krallıklarını düşürdüler, 2799’da yeraltı şehirlerini bastılar.","3050’de Horaghfus ırklarının savaşıyla soyları tükendi."],"ph":[{"f":"assets/tagimg/2cfb79e74cb1.webp?v=e7345a6eef","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Mital Alari muhafızları":{"t":"f","sub":"Mital Alari şehir muhafızları","bio":["Mital Alari’nin şehir muhafızları; tahliyeden sonra Gideon’un askeri Tom bunların kaptanı oldu."],"ph":[{"f":"assets/tagimg/d8ca93a37663.webp?v=868cd735db","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Olik Tarikatı krallığı":{"t":"f","sub":"Bereket Nehri’ndeki krallık","bio":["Blavinken’in kuzeyinde Bereket Nehri’nin üstüne kurulmuş dinî krallık; 9443’te Prens Askar’a yenildi."],"ph":[{"f":"assets/tagimg/c2643c5f989b.webp?v=e4dfd679d3","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Orclar":{"t":"f","sub":"Orc ırkı","bio":["9735 kaydında yalnızca başlık olarak geçer: “Işık Elfleri’nin Orc’a dönüştürülmesi”."],"ph":[{"f":"assets/tagimg/84fedf36d996.webp?v=fdc7491e5f","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Strömbah klanı":{"t":"f","sub":"Cüce klanı","bio":["Strömbah dağının cüce klanı. 7671’de festival yarışında Bronzçınar klanının sırasını çalınca Kabza Gurur Savaşı çıktı."],"ph":[{"f":"assets/tagimg/40eadf5004ca.webp?v=513b2ff070","w":1280,"h":720,"cap":"Temsilî çizim"}]},"Üç ırk (insan, elf, cüce)":{"t":"f","sub":"Boraldmir’e karşı birleşen ırklar","bio":["İnsan, elf ve cüce ırkları. Boraldmir’in ruhunu hapseden hançeri birlikte dövdüler; Büyük Savaş’ta Revalor onları birleştirdi ve Boraldmir yenildi."],"alias":["Üç ırk"],"ph":[{"f":"assets/tagimg/6c112d21a524.webp?v=82d6e9c2b9","w":1280,"h":720,"cap":"Temsilî çizim"}]},"İmparatorluk donanması":{"t":"f","sub":"İmparatorluğun deniz gücü","bio":["İmparatorluğun donanması. Balahnur limanındaki Man o’ War gemisinde minotorlar saldırıya geçti. Prens Michael’ın ortağı olduğu IN-co (Imperial Navy) donanma gemileri üretir."],"ph":[{"f":"assets/tagimg/b8851233d09d.webp?v=cc89a7ca92","w":1280,"h":720,"cap":"Temsilî çizim"}]},"İnsanlar":{"t":"f","sub":"İnsan ırkı","bio":["Horaghfus’un insan ırkı. Kobold Gazabı’ndan sonra teknolojide geriledi; Khotekx savaşlarında Koboldları yendi. Aidiyet Savaşları’nda kendi krallıklarına ayrıştı, 9450’de Narnold’un İmparatorluğu’nda birleşti.","9455’te savaşlardan kaçan insan mülteciler elf ülkelerine sığındı."],"alias":["İnsan kabileleri","İnsan krallıkları","İnsan mülteciler"],"ph":[{"f":"assets/tagimg/57b1916b60d1.webp?v=2a556e7b42","w":1280,"h":720,"cap":"Temsilî çizim"}]}};
